['Here is a high-level design of your program in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct Data {
    int max_value;
    long long sum;
    size_t count;
} Data;

void processFile(FILE *file, Data* result) {
    if (result == NULL || file == NULL) {
        fprintf(stderr, "Invalid input!\n");
        exit(EXIT_FAILURE);
    }

    int currentValue = 0;
    while (fscanf(file, "%d", &currentValue) == 1) {
        if (result->count == 0 || currentValue > result->max_value) {
            result->max_value = currentValue;
        }
        if (LLONG_MAX - result->sum < currentValue) { // check overflow
            fprintf(stderr, "Overflow warning!\n");
            exit(EXIT_FAILURE);
        }
        result->sum += currentValue;
        result->count++;
    }
}

int main() {
    Data result = {0};
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    processFile(file, &result);
    double average = 0.0;
    if (result.count > 0) {
        average = (double) result.sum / (double) result.count;
    }

    fclose(file);
    printf("Maximum value: %d\n", result.max_value);
    printf("Average value: %f\n", average);

    return EXIT_SUCCESS;
}
```
This is a simple C program that reads an integer from each line of the file "input.txt" and updates max, sum and count of integers. If overflow happens during the addition of currentValue to sum, it terminates gracefully with an error message. 
