import org.springframework.cache.annotation.*;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.bind.annotation.*;

@RestController
@EnableCaching
public class PokemonTypeService {

    private final TypeChartFetcher typeChartFetcher;

    public PokemonTypeService(TypeChartFetcher typeChartFetcher) {
        this.typeChartFetcher = typeChartFetcher;
    }

    @Scheduled(fixedRate = 24 * 60 * 60 * 1000) // Every 24 hours
    @CacheEvict(value = "pokemonType", allEntries = true)
    public void fetchLatestTypeChart() {
        typeChartFetcher.fetch();
    }

    @GetMapping("/type/{name}")
    @Cacheable("pokemonType")
    public PokemonType getPokemonType(@PathVariable String name) {
        return typeChartFetcher.get(name);
    }

    @ExceptionHandler({ RuntimeException.class })
    public ResponseEntity<Object> handleAll(RuntimeException ex, WebRequest request) {
        ApiError apiError = new ApiError(HttpStatus.INTERNAL_SERVER_ERROR, ex.getLocalizedMessage(), "error occurred");
        return new ResponseEntity<>(apiError, new HttpHeaders(), apiError.getStatus());
    }
}
```
In this example, we're scheduling the `fetchLatestTypeChart` method to run every 24 hours and evicting all cached entries for "pokemonType" after it runs. This ensures that our type chart data is always up-to-date. We use a REST controller method to expose an endpoint which fetches and returns the requested Pokemon type from cache.

