        {
            // Handle network timeouts
            return new WeatherData() { Temperature = "N/A" };
        }
        catch (JsonReaderException)
        {
            // Handle corrupted or incomplete data 
            return new WeatherData() { Temperature = "N/A" };
        }

        return new WeatherData() { Temperature = "N/A" };
    }
}
```
