JavaScript component:
```javascript
const copyBytes = (buffers, byteCount) => {
  if(byteCount > buffers.reduce((total, buffer) => total + buffer.length, 0)) {
    throw new Error("Requested byte count exceeds available bytes");
  }

  let copiedBytes = 0;
  const result = Buffer.allocUnsafe(byteCount);

  for (let i = 0; i < buffers.length && copiedBytes < byteCount; i++) {
    const buffer = buffers[i];

    if (copiedBytes + buffer.length <= byteCount) {
      // Copy entire chunk
      buffer.copy(result, copiedBytes);
      copiedBytes += buffer.length;
    } else {
      // Only copy remaining bytes in current chunk
      const remaining = byteCount - copiedBytes;
      buffer.slice(0, remaining).copy(result, copiedBytes);
      copiedBytes += remaining;
    }
  }

  return result;
}
```
