} ResourceItem;

int loadResourceBundle(const char *filename, ResourceItem **items, int *itemCount) {
  FILE *file = fopen(filename, "rb"); // Open file in binary read mode

  if (file == NULL) return -1; // Return error code if failed to open file

  // Determine the size of the file
  fseek(file, 0L, SEEK_END);
  long size = ftell(file);
  rewind(file);

  char *buffer = (char *)malloc(size); // Allocate memory for buffer to hold contents of file

  if (fread(buffer, sizeof(char), size, file) != size) {
    fclose(file);
    free(buffer);
    return -2; // Return error code if failed to read file or mismatch in bytes count
  }

  // Parse buffer into items (This is application-specific and depends on the format of your bundle)
