<?php
class UserService {
    private $externalAuthApi;

    public function __construct($api) {
        $this->externalAuthApi = $api;
    }

    public function updateUserPassword($username, $newPassword) {
        if (!$this->validatePassword($newPassword)) {
            return ['success' => false, 'message' => 'Invalid password'];
        }

        $hashedNewPassword = $this->securelyHashPassword($newPassword);

        $maxAttempts = 3;
        $attemptCount = 0;

        do {
            $updateResponse = $this->externalAuthApi->updatePassword($username, $hashedNewPassword);
            ++$attemptCount;
            if ($updateResponse['success']) {
                return ['success' => true];
            }
            sleep(pow(2, $attemptCount)); // Exponential backoff
        } while ($attemptCount < $maxAttempts);

        return ['success' => false, 'message' => 'Failed to update password after several attempts'];
    }

    private function validatePassword($password) {
        $validator = new PasswordValidator(); // third-party library for password validation
        return $validator->isValid($password);
    }

    private function securelyHashPassword($password) {
        return password_hash($password, PASSWORD_ARGON2I); // Secure hashing
    }
}
?>
