["Here's a simplified example to address some of your requirements using C programming language, focusing on points 1,2,3,5 and 7:
```c
#include <pthread.h>
#include <stdlib.h>

typedef struct fsa_state {
    int state;
    struct fsa_state *next;
} FSAState;

typedef int (*FSAFilter)(int);

// Global mutex for locking access to the list of states
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

FSAState *filter_states(int* states, int size, FSAFilter filter) {
    pthread_mutex_lock(&mutex);  // Lock to avoid concurrent modifications

    FSAState dummy = {.state=-1, .next=NULL}, *tail = &dummy;
    for(int i = 0; i < size; ++i) {
        if (filter && filter(states[i])) {  // Apply filter callback
            FSAState *node = malloc(sizeof(*node));  // Allocate memory dynamically

            if (!node) {
                pthread_mutex_unlock(&mutex);  // Unlock on memory allocation failure
                return NULL;
            }

            node->state = states[i];  // Add state to the list
            node->next = NULL;
            tail = tail->next = node;
        }
    }

    pthread_mutex_unlock(&mutex);  // Unlock after modifications

    FSAState *filtered_states = dummy.next;
    return filtered_states;
}
```
This code defines a simple linked list structure `FSAState` to store states and applies the filter callback function provided by the user to dynamically allocate memory for the filtered states from an array of states. 

To adapt this code into your system, you would need to integrate it with your existing database connection handling mechanisms (not shown here) and handle any other dependencies or integration points in your existing codebase. Also, ensure that appropriate error checking and handling mechanisms are put in place for potential issues such as invalid inputs or database failures. 

