    int totalFields = 0;
    double sum = 0;

    while ((read = getline(&line, &len, inputFile)) != -1) {
        char *field = strtok(line, ",");
        while (field != NULL) {
            char *endptr;
            double num = strtod(field, &endptr);

            if (*endptr == '\0' && field != endptr) {  // A numeric field.
