            }

            field = strtok(NULL, ",");
        }

        if (totalFields == 0) {
            fprintf(outputFile, "%s,\n", line);
        } else {
            double avg = sum / totalFields;
            fprintf(outputFile, "%s,%f\n", line, avg);
