```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void renameFiles(char *dirPath) {
    DIR *d;
    struct dirent *dir;
    d = opendir(dirPath);

    if (d) {
        while ((dir = readdir(d)) != NULL) {
            char oldpath[256];
            strcpy(oldpath, dir->d_name);

            // Ignore hidden files/directories or "." and ".."
            if (oldpath[0] == '.') continue; 

            struct stat attr;
            char newpath[256];

            strcpy(newpath, dir->d_name);
            // Add timestamp to filename. You may want to use a more complex versioning scheme.
            sprintf(newpath, "%ld%s", time(NULL), oldpath); 

            if (stat(oldpath, &attr) == 0) {
                pthread_mutex_lock(&mutex); // Lock mutex to ensure safety while renaming files concurrently.

                if (rename(oldpath, newpath) < 0) { 
                    fprintf(stderr, "Rename failed with error %d\n", errno);
                } else {
                    printf("Renamed '%s' to '%s'\n", oldpath, newpath);
                }

                pthread_mutex_unlock(&mutex); // Unlock mutex after operation.
            } else {
                fprintf(stderr, "Stat failed with error %d\n", errno);
            }
        }

        closedir(d);
    }
}
```

This is a simple example of how one might implement file renaming in C. This code assumes that the directory path given to `renameFiles` function exists and is accessible. There are numerous ways this could be improved, including adding support for nested directories, more complex versioning schemes (like incremental versions), better error handling, concurrency control with thread safety, etc. 

