int convertImages(char *dir_path, char *output_name, 
                  char *target_format, int allow_overwrite) {
    DIR *dir;
    struct dirent *ent;
    pthread_t threads[10]; // assuming max 10 concurrent conversions for simplicity
    convert_args_t args[10];
    int thread_count = 0;

    if ((dir = opendir (dir_path)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            // Checking for valid image file
            char *extension = strrchr(ent->d_name, '.');
            if (strcmp(extension, ".jpg") == 0 || strcmp(extension, ".png") == 0) {
                char *src_path = malloc(strlen(dir_path) + strlen(ent->d_name) + 2);
                sprintf(src_path, "%s/%s", dir_path, ent->d_name);

                // Check for permissions and ownership of the file
                struct stat st;
                stat(src_path, &st);
                if (getuid() != st.st_uid) {
                    printf("Insufficient permissions detected.\n");
                    free(src_path);
                    return -2;
                }

                // Create thread for each image conversion and pass necessary parameters
                args[thread_count].dir_path = src_path;
                args[thread_count].output_name = output_name;
                args[thread_count].target_format = target_format;
                args[thread_count].allow_overwrite = allow_overwrite;
                pthread_create(&threads[thread_count], NULL, convert_image, &args[thread_count]);

                thread_count++;
            }
        }
        closedir (dir);
    } else {
        perror ("Could not open directory");
        return -1; // Directory does not exist or is inaccessible
    }

    // Wait for all threads to finish and check if any of them failed
    int i, status;
    for (i = 0; i < thread_count; i++) {
        pthread_join(threads[i], (void *) &status);
        free(args[i].dir_path); // Free allocated memory
        if (!status) {
            return 1; // Conversion failed
        }
    }

    return 0; // All conversions succeeded
}
```
