import java.nio.file.*;
import java.util.Comparator;
import java.util.stream.Stream;

public class FileManagementService {
    private static final Logger logger = Logger.getLogger(FileManagementService.class);
    private CloseableHttpClient httpclient = HttpClients.createDefault();

    public void deleteDirectoryRecursively(Path path) throws IOException {
        try (Stream<Path> walk = Files.walk(path)) {
            walk.sorted(Comparator.reverseOrder())
                .map(Path::toFile)
                .forEach(File::delete);
        } catch (IOException e) {
            logger.error("Error deleting directory: " + path, e);
            throw new IOException("Failed to delete directory: " + path, e);
        }
    }

    public String callExternalAPI(String url) throws IOException {
        HttpGet httpget = new HttpGet(url);

        try (CloseableHttpResponse response = httpclient.execute(httpget)) {
            return response.toString();
        } catch (IOException e) {
            logger.error("Failed to call external API: " + url, e);
            throw new IOException("Failed to call external API: " + url, e);
        }
    }
}
```
