using System;
using System.IO;
using System.Security.Cryptography;
using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.Extensions.Logging;

public class DataDecryptionService<T> where T : struct
{
    private readonly ILogger _logger;

    public byte[] Key { get; set; }
    public byte[] IV { get; set; }

    public DataDecryptionService(ILogger logger)
    {
        this._logger = logger;
    }

    public T DecryptAndDeserialize(Stream encryptedData)
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = Key;
                aesAlg.IV = IV;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream())
                {
                    using (CryptoStream csDecrypt = new CryptoStream(encryptedData, decryptor, CryptoStreamMode.Read))
                    {
                        csDecrypt.CopyTo(msDecrypt);
                    }

                    BinaryFormatter bf = new BinaryFormatter();

                    return (T)bf.Deserialize(msDecrypt);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError("Failed to decrypt and deserialize data.", ex);

            throw;
        }
    }
}
```

