["Here's an outline of how you might approach implementing this file uploading service in JavaScript. 

This code block does not include the actual implementation due to complexity and size constraints. But it provides a basic structure that can be built upon. Please, adjust and adapt according to your specific requirements.

```javascript
// Required Dependencies
const axios = require('axios');
const fs = require('fs');

class UploadService {
  constructor(config) {
    this.metadataServiceURL = config.metadataServiceURL;
    this.maxFileSizeInMB = config.maxFileSizeInMB || 100; // Default max file size is 100 MB
    this.supportedMimeTypes = config.supportedMimeTypes || [];
    this.uploadQueue = [];
    this.activeUploads = 0;
    this.callbacks = {
      onStart: () => {},
      onProgress: (progress) => {},
      onComplete: (url) => {}
    };
  }

  setCallbacks(callbacks) {
    this.callbacks = callbacks;
  }

  uploadFile(filePath, metadata) {
    return new Promise((resolve, reject) => {
      // Check file size and MIME type
      const stats = fs.statSync(filePath);
      if (stats['size'] > this.maxFileSizeInMB * 1024 * 1024) {
        return reject('File exceeds maximum size limit');
      }

      const mimeType = getMIMETypeFromFile(filePath); // Implementation depends on the file system being used
      if (!this.supportedMimeTypes.includes(mimeType)) {
        return reject('Unsupported MIME type');
      }

      // Enqueue upload and start processing it once there are no active or queued uploads
      this.uploadQueue.push({filePath, metadata, resolve, reject});
      if (this.activeUploads === 0) {
        this.processNextFile();
      }
    });
  }

  processNextFile() {
    const nextItem = this.uploadQueue.shift();
    if (!nextItem) return;

    // Start upload and handle progress updates
    this.activeUploads++;
    this.callbacks.onStart(nextItem);
    axios.post('/files', fs.createReadStream(nextItem.filePath))
      .then((response) => {
        const url = response.data.url;

        // Associate metadata with the file
        return axios.put(`${this.metadataServiceURL}/${url}`, nextItem.metadata);
      })
      .then((response) => {
        this.activeUploads--;
        this.callbacks.onComplete(nextItem);

        // Resolve the promise to notify the caller of successful upload and URL
        nextItem.resolve(url);

        // Start processing next file in the queue
        this.processNextFile();
      })
      .catch((error) => {
        this.activeUploads--;
        this.callbacks.onComplete(nextItem, error);

        // Retry upload with exponential backoff and maximum number of attempts
        if (nextItem.attempts < MAX_ATTEMPTS) {
          setTimeout(() => {
            nextItem.attempts++;
            this.uploadQueue.unshift(nextItem);
            this.processNextFile();
          }, BACKOFF_INTERVAL * Math.pow(2, nextItem.attempts)); // Adjust exponential backoff interval as needed
        } else {
          // Reject the promise to notify the caller of failed upload with error details
          nextItem.reject(error);

          // Start processing next file in the queue
          this.processNextFile();
        }
      });
  }
}
```
This is a simple implementation and does not cover all scenarios such as cancelling ongoing requests, UI integration for retrying and cancelling, etc. Please refer to JavaScript library documentation for more details on handling these features. Also, this code assumes usage of the Axios library for making HTTP requests and Node.js file system module for interacting with files. You may need to adjust it according to your specific use case and environment.
"]

