    printf("Original: %s\n", text);
    printf("Encrypted: %s\n", cipher);
    printf("Decrypted: %s\n", decrypted);

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(text, strlen((char *)text), hash);

    printf("Hash: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    return 0;
}
