use tokio::sync::Semaphore;
use std::time::Duration;
use anyhow::Result;
use reqwest::Url;
use serde::Deserialize; // Use serde to parse JSON responses from APIs

#[derive(Debug, Deserialize)]
struct ApiData { /* Define data structure here */ }

async fn fetch_data(client: &reqwest::Client, url: Url) -> Result<ApiData> {
    let response = client.get(url).send().await?;
    let api_data: ApiData = response.json().await?;
    Ok(api_data)
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize HTTP client with timeout
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(5))
        .build()?;

    // Define a semaphore to limit concurrency 
    let semaphore = Semaphore::new(50);

    // List of URLs for different APIs
    let urls: Vec<Url> = vec![];

    tokio::spawn({
        let urls_clone = urls.clone();
        let client_clone = client.clone();
        async move {
            // Iterate over URLs and fetch data concurrently
            for url in urls_clone {
                semaphore.acquire().await;

                tokio::spawn(async move {
                    if let Err(e) = fetch_data(&client_clone, url) {
                        eprintlnlnto::stderr(), "Error fetching data from API: {}", e);
                    }
                });
            }
        }
    });

    Ok(())
}
``` 
