```python
class SchemaRegistry(object):
    def __init__(self, schemas=None):
        self._schemas = schemas or {}

    def add_schema(self, name, schema):
        self._schemas[name] = schema

    def get_factory(self, name, **kwargs):
        if name not in self._schemas:
            raise ValueError("Schema '{}' does not exist.".format(name))
        return lambda data: self._schemas[name](data, **kwargs)
```
2. Lazy Evaluation:

```python
class LazyJSONObject(object):
    def __init__(self, json_str):
        self._json_str = json_str
        self._loaded = False
        self._dict = None

    def _load(self):
        if not self._loaded:
            self._dict = json.loads(self._json_str)
            self._loaded = True

    def __getattr__(self, name):
        self._load()
        return self._dict[name]
```
