```csharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public interface IDataValidator<T>
{
    bool Validate(T data);
}

// For simplicity, this just verifies that the data isn't null
public class DefaultDataValidator<T> : IDataValidator<T> 
{
    public bool Validate(T data) => data != null;
}

public static class DataLoader
{
    private const string ConfigPath = "config/path.txt";

    // Loads and validates the binary file at the specified path using BinaryFormatter, 
    // falling back to a default validator if one isn't provided
    public static T LoadAndValidateData<T>(string configPath = ConfigPath, IDataValidator<T> validator = null)
    {
        validator ??= new DefaultDataValidator<T>();

        using var fs = new FileStream(configPath, FileMode.Open);
        var formatter = new BinaryFormatter();
        try
        {
            var data = (T)formatter.Deserialize(fs);
            if (!validator.Validate(data)) 
                throw new InvalidDataException("Invalid data.");

            return data;
        }
        catch (Exception ex)
        {
            // handle error
            Console.WriteLine(ex.Message);
            throw;
        }
    }
}
```

This code reads a path to the binary file from a configuration file, then deserializes it into an instance of `T` using `BinaryFormatter`. It uses a default validator if no validator is provided. 

