```cpp
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string>
#include <iostream>

constexpr int ITERATIONS = 4096; // Adjust this based on performance requirements
constexpr int KEY_LEN = 32; 
constexpr int IV_LEN = 16; 

bool deriveKeyIv(std::string password, unsigned char* key, unsigned char* iv) {
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), nullptr, 
        reinterpret_cast<const unsigned char*>(password.data()), password.size(), ITERATIONS, key, iv)) {

        std::cerr << "Failed to derive key and IV" << std::endl;
        return false;
    }

    return true;
}

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

int encrypt(unsigned char* plaintext, int plaintext_len, unsigned char* key,
            unsigned char* iv, unsigned char* ciphertext) {

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new(); 
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();

    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) handleErrors();

    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) handleErrors();

    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx); 
    return ciphertext_len;
}

int decrypt(unsigned char* ciphertext, int ciphertext_len, unsigned char* key,
            unsigned char* iv, unsigned char* plaintext) {

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new(); 
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();

    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) handleErrors();

    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) handleErrors(); 

    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx); 
    return plaintext_len;
}
```
