['Here is a Python-based sample solution that might fulfill some of your requirements:
```python
import asyncio
import logging
from collections import defaultdict
from datetime import datetime

class RateLimiter:
    def __init__(self, limit):
        self.limit = limit
        self.window_counts = defaultdict(int)
        self.ip_windows = {}

    async def allow_request(self, ip):
        now = datetime.now()
        current_window = int(now.timestamp()) // 10

        if ip in self.ip_windows:
            last_window = self.ip_windows[ip]
            if last_window != current_window:
                self.window_counts[last_window] = 0
        else:
            self.ip_windows[ip] = current_window - 1

        self.window_counts[current_window] += 1
        if self.window_counts[current_window] > self.limit:
            logging.warning(f"Rate limit exceeded by {ip}")
            return False

        self.ip_windows[ip] = current_window
        return True

class RateLimitMiddleware:
    def __init__(self, app, limiter):
        self.app = app
        self.limiter = limiter

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":  # pragma: no cover
            return await self.app(scope, receive, send)

        ip_address = scope['client'][0]

        if not await self.limiter.allow_request(ip_address):
            await send({
                'type': 'http.response.start',
                'status': 429, # Too Many Requests HTTP status code
                'headers': [
                    [b'content-type', b'text/plain'],
                ]
            })
            return await send({
                'type': 'http.response.body',
                'body': b'Too Many Requests',
            })

        return await self.app(scope, receive, send)
```
This is a simplified example and doesn't include all requirements like anomaly detection from external sources or configuration management systems integration. The rate-limiter just tracks the number of requests in the current window and if the limit is exceeded it rejects new requests. You should use this as a starting point for your application and adjust according to your needs.

Please note that writing production-grade code requires careful design, thorough testing, robust error handling, and security considerations like protecting against injection attacks etc. Please consult with an experienced software developer to ensure the solution is fit for purpose.
']

