    // Create a socket and establish secure connection with external data source
    sockfdExternal = socket(AF_INET, SOCK_STREAM, 0);
    addrExternal.sin_family = AF_INET;
    addrExternal.sin_port = htons(externalDataSourcePort);
    inet_pton(AF_INET, externalDataSourceIP, &addrExternal.sin_addr);
    connect(sockfdExternal, (struct sockaddr *)&addrExternal, sizeof(addrExternal));
    // Create a new BIO for the socket and attach it to SSL structure
    bioExternal = BIO_new_socket(sockfdExternal, BIO_NOCLOSE);
    BIO_get_ssl(bioExternal, &sslExternal);
    SSL_set_mode(sslExternal, SSL_MODE_AUTO_RETRY);
    // Perform TLS handshake with external data source
