void *resolveDNS(void *arg) {
    char* hostname = (char*) arg;
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        Provider* provider = select_provider(providers, num_providers); // get selected DNS provider 

        char url[1024];
        sprintf(url, "https://%s/dns-query?name=%s", provider->api_key, hostname); // construct URL for DNS resolution API call

        curl_easy_setopt(curl, CURLOPT_URL, url);

        res = curl_easy_perform(curl);

        /* Check for errors */ 
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
    }

    pthread_exit(NULL); // exit the thread
}

int main() {
    Provider* providers[2];  // Array of DNS providers to be used
    providers[0] = malloc(sizeof(Provider));
    providers[1] = malloc(sizeof(Provider));

    pthread_t thread;
    char hostname[] = "example.com";
    int err;

    if((err = pthread_create(&thread, NULL, resolveDNS, (void*)hostname)) != 0) {
