public class CustomDistributionGenerator {

    private Supplier<Double> uniformDistribution = () -> ThreadLocalRandom.current().nextDouble();
    private RealDistribution gaussianDistribution = new NormalDistribution(0, 1);
    private RealDistribution exponentialDistribution = new ExponentialDistribution(1);

    public double generateUniform() {
        return uniformDistribution.get();
    }

    public double generateGaussian() {
        return gaussianDistribution.sample();
    }

    public double generateExponential() {
        return exponentialDistribution.sample();
    }
}
