    public function updatePassword($userId, $newPassword) {
        // Validate password with Argon2id library
        if (!$this->passwordValidator::verify($newPassword)) {
            throw new Exception("Invalid password");
        }

        $client = new Client();
        $apiUrl = $this->authApiUrl;

        // If the primary authentication API is unavailable, switch to backup
        if (!$this->isServiceAvailable($this->authApiUrl)) {
            $apiUrl = $this->backupAuthApiUrl;
            // Here you might also want to send an alert or log this event for further investigation
        }

        $headers = [
          'Content-Type' => 'application/json', 
          'Authorization' => 'Bearer yourToken' // replace with actual token
        ];

        try {
            $response = $client->post($apiUrl . '/users/' . $userId, ['headers' => $headers,'body' => $newPassword]);

            if ($response->getStatusCode() !== 200) {
                throw new Exception("Failed to update password: " . $response->getReasonPhrase());
            }
        } catch (GuzzleException $e) {
            throw new Exception("HTTP Request failed: " . $e->getMessage());
        }

        $this->redisClient->set('passwordUpdate:' . $userId, time()); // Store password update timestamp in cache
    }

    private function isServiceAvailable($url) {
      try {
          $client = new Client();
          $response = $client->get($url);
          return true;
      } catch (Exception $e) {
          // Log the exception for further analysis
          error_log("Failed to connect to " . $url . ": " . $e->getMessage());
          return false;
      }
    }
}
?>
