class CacheEntry {
public:
    CacheEntry(const std::string& data, const int ttl) : 
        mData(data), mExpirationTime(std::chrono::system_clock::now() + std::chrono::seconds(ttl)) {}

    bool IsExpired() const {
        return std::chrono::system_clock::now() > mExpirationTime;
    }

    std::string GetData() const {
        // Add locking mechanism if required, this is just a simplified example
        return mData;
    }

private:
    std::string mData;
    std::chrono::time_point<std::chrono::system_clock> mExpirationTime;
};

class Cache {
public:
    void Set(const std::string& key, const std::string& value, int ttl) {
        // Add locking mechanism if required, this is just a simplified example
        mCache[key] = std::make_unique<CacheEntry>(value, ttl);
    }

    bool Get(const std::string& key, std::string& value) const {
        auto it = mCache.find(key);

        if (it != mCache.end() && !it->second->IsExpired()) {
            // Add locking mechanism if required, this is just a simplified example
            value = it->second->GetData();
            return true;
        }

        return false;  // Not found or expired
    }

private:
    mutable std::shared_mutex mRWLock;
    std::unordered_map<std::string, std::unique_ptr<CacheEntry>> mCache;
};
```
The Cache class provides thread-safe access to the data store and handles expiration of entries. It uses shared locks for read operations and unique lock for write operations which reduces contention between multiple threads reading from cache. However, in practice a more complex solution would be needed to handle edge cases like handling eviction during write operation etc.

