However, I can provide an example of a simple C program that renames all files in a directory to the current timestamp:

```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <string.h>

void rename_files(const char *dir) {
    DIR *dp;
    struct dirent *entry;
    struct stat statbuf;

    if((dp = opendir(dir)) == NULL) {
        fprintf(stderr, "Cannot open directory: %s\n", dir);
        return;
    }

    chdir(dir);

    while ((entry = readdir(dp)) != NULL) {
        stat(entry->d_name, &statbuf);
        if (S_ISDIR(statbuf.st_mode)) {
            // Ignore directories
            continue;
        } else {
            char newName[100];
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            sprintf(newName, "%d-%02d-%02d_%02d:%02d:%02d", 
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec);
            strcat(newName, entry->d_name);

            if (rename(entry->d_name, newName) != 0) {
                fprintf(stderr, "Cannot rename file: %s\n", entry->d_name);
            }
        }
    }

    closedir(dp);
}

int main() {
    const char *dir = "/path/to/directory";
    rename_files(dir);

    return 0;
}
```
This code will rename all files in the specified directory to a timestamp. It's very simple and does not include many of the features you mentioned but should provide a starting point for further development. For more complex tasks, it would be beneficial to break down these features into smaller sub-tasks and implement each one separately.
