using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Security.Cryptography;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class DynamicDataIngestor : IDisposable
{
    private readonly ConcurrentQueue<dynamic> _queue = new ConcurrentQueue<dynamic>();
    private readonly CancellationTokenSource _cancellationTokenSource = new CancellationTokenSource();
    private readonly AesGcm _aes;
    private readonly IConfiguration _configuration;
    private readonly ILogger<DynamicDataIngestor> _logger;

    public DynamicDataIngestor(IConfiguration configuration, ILogger<DynamicDataIngestor> logger)
    {
        _aes = new AesGcm("key"); // Fetch key from key management service or HSM here.
        _configuration = configuration;
        _logger = logger;

        // Start processing thread with optimal degree of parallelism based on system config.
        var threadsCount = Environment.ProcessorCount * _configuration.GetValue<int>("ThreadsMultiplier");
        for (var i = 0; i < threadsCount; ++i)
            new Thread(Process).Start();
    }

    public void Dispose() => _cancellationTokenSource.Cancel();

    public void IngestData(dynamic data)
    {
        // Decrypt and enqueue the decrypted data here.
        var decryptedData = _aes.Decrypt(data);
        _queue.Enqueue(decryptedData);
    }

    private void Process()
    {
        while (!_cancellationTokenSource.IsCancellationRequested)
        {
            // Dequeue data from queue and process here.
            if (_queue.TryDequeue(out var data))
                ProcessData(data);

            Thread.Sleep(_configuration.GetValue<int>("ProcessingInterval")); // Add delay to balance load across threads.
        }
    }

    private void ProcessData(dynamic data)
    {
        try
        {
            // Process decrypted data here.
            Console.WriteLine(data);
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Failed to process data");
        }
    }
}
```
