```cpp
#include <dlfcn.h>
#include <iostream>
#include <vector>

typedef void* ModelHandle;

ModelHandle load_model(const std::string& path) {
    return dlopen(path.c_str(), RTLD_NOW | RTLD_GLOBAL);
}

void unload_model(ModelHandle handle) {
    if (handle) {
        dlclose(handle);
    }
}

typedef void (*PredictFunc)(const std::vector<float>& input, std::vector<float>* output);

PredictFunc get_predict_func(ModelHandle handle) {
    return reinterpret_cast<PredictFunc>(dlsym(handle, "predict"));
}

int main() {
    ModelHandle model = load_model("path/to/your/lib.so");

    if (!model) {
        std::cerr << "Failed to load model: " << dlerror() << "\n";
        return 1;
    }

    PredictFunc predict = get_predict_func(model);

    if (!predict) {
        std::cerr << "Failed to find 'predict' function in the loaded module\n";
        unload_model(model);
        return 2;
    }

    // ... Here you would normally get your input from an external data source.
