import numpy as np
from enum import Enum
import threading

class DistType(Enum):
    UNIFORM = 1
    GAUSSIAN = 2
    EXPONENTIAL = 3
    CUSTOM = 4

class RandomNumberGenerator:
    def __init__(self, seed=None):
        self.lock = threading.Lock()
        if seed is not None:
            np.random.seed(seed)

    def generate_number(self, distribution_type=DistType.UNIFORM):
        with self.lock:
            if distribution_type == DistType.UNIFORM:
                return np.random.rand()
            elif distribution_type == DistType.GAUSSIAN:
                return np.random.normal()
            elif distribution_type == DistType.EXPONENTIAL:
