        private readonly MemoryCache _cache;
        private readonly OAuth2Client _oauthClient;

        public ConfigurationManager(string redisConnectionString)
        {
            // Create a Redis connection
            _redisConnection = ConnectionMultiplexer.Connect(redisConnectionString);

            // Create a memory cache
            var cacheOptions = new MemoryCacheOptions();
            _cache = new MemoryCache(cacheOptions);

            // Create an OAuth2 client for API security
            _oauthClient = new OAuth2Client("clientId", "clientSecret");
        }

        public string GetConfiguration(string configKey)
        {
            // Check local cache first
            if (_cache.TryGetValue(configKey, out string config))
                return config;

            // If not in local cache, check Redis cache
            var db = _redisConnection.GetDatabase();
            config = db.StringGet(configKey);

            if (string.IsNullOrEmpty(config))
            {
                // If not in Redis either, fetch from source and update both caches
                config = FetchConfigurationFromSource(configKey);
                UpdateCaches(configKey, config);
            }

            return config;
        }

        private string FetchConfigurationFromSource(string configKey)
        {
            // Fetch configuration logic here
            throw new NotImplementedException();
        }

        private void UpdateCaches(string key, string value)
        {
            // Local cache update logic here
            _cache.Set(key, value);

            // Redis cache update logic here
            var db = _redisConnection.GetDatabase();
            db.StringSet(key, value);
        }

