import java.io.*;

public class Serializer {
    public void serializeObject(String filename, Object obj) {
        try (FileOutputStream fileOut = new FileOutputStream(filename);
             ObjectOutputStream out = new ObjectOutputStream(fileOut)) {
            out.writeObject(obj);
        } catch (IOException e) {
            System.out.println("Error serializing object: " + e.getMessage());
        }
    }

    public Object deserializeObject(String filename) {
        try (FileInputStream fileIn = new FileInputStream(filename);
             ObjectInputStream in = new ObjectInputStream(fileIn)) {
            return in.readObject();
        } catch (IOException e) {
            System.out.println("Error reading object: " + e.getMessage());
            return null;
        } catch (ClassNotFoundException e) {
            System.out.println("Invalid class definition in file: " + filename);
            return null;
        }
    }
}
```
