void deleteDirectory(char *path) {
    DIR *dir = opendir(path);

    if (dir == NULL) return; // Could not open directory 

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char entry_path[512];
        snprintf(entry_path, sizeof(entry_path), "%s/%s", path, entry->d_name);

        if (entry->d_type == DT_DIR) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue; // Ignore . and .. 

            deleteDirectory(entry_path); // Recursive call to handle subdirectories
        } else {
            remove(entry_path); // Delete file 
        }
    }

    closedir(dir);
    rmdir(path); // Remove directory itself after deleting all contents
}
```
