```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

class ThreadSafeCounter {
public:
    void increment() {
        std::lock_guard<std::mutex> lock(mMutex);
        ++counter;
    }

    void decrement() {
        std::lock_guard<std::mutex> lock(mMutex);
        --counter;
    }

    int getValue() const {
        return counter;
    }
private:
    mutable std::mutex mMutex;
    int counter = 0;
};

int main() {
    ThreadSafeCounter counter;
    std::vector<std::thread> threads;

    for (int i = 0; i < 5; ++i) {
        threads.push_back(std::thread([&counter](){
            for (int i = 0; i < 100; ++i) { counter.increment(); }
        }));
    }

    for (auto &t : threads) {
        t.join();
    }

    std::cout << "Counter value: " << counter.getValue() << "\n";
    return 0;
}
```

