using System;
using System.Threading;
using System.Numerics;
using Newtonsoft.Json;
using StackExchange.Redis;
using System.Collections.Concurrent;

public class DynamicRandomValueService : IDisposable
{
    private readonly ConcurrentDictionary<string, ThreadLocal<Random>> _randoms = new ConcurrentDictionary<string, ThreadLocal<Random>>();
    private readonly ConnectionMultiplexer _redis;
    private readonly IDatabase _db;

    public DynamicRandomValueService(string redisConnectionString)
    {
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        _db = _redis.GetDatabase();
    }

    public float GenerateFloat(string seed, float min, float max)
    {
        var random = GetOrCreateRandom(seed);
        return (float)(min + (random.NextDouble() * (max - min)));
    }

    public int GenerateInteger(string seed, int min, int max)
    {
        var random = GetOrCreateRandom(seed);
        return random.Next(min, max);
    }

    private ThreadLocal<Random> GetOrCreateRandom(string seed)
    {
        // Use a custom comparer to ensure the seed is case sensitive for case insensitive file systems like Linux
        return _randoms.GetOrAdd(seed, s => new ThreadLocal<Random>(() => LoadGeneratorStateFromRedis(s), trackAllValues: false));
    }

    private Random LoadGeneratorStateFromRedis(string seed)
    {
        var state = _db.StringGet($"random-generator-state:{seed}");

        if (state.IsNullOrEmpty) return new Random(); // Default seed for a new generator 

        try
        {
            var randomState = JsonConvert.DeserializeObject<Random>(state);

            // If deserialization fails, use the default seed instead
            if (randomState == null) throw new Exception("Failed to deserialize state");

            return randomState;
        }
        catch
        {
            return new Random(); 
        }
    }

    public void SaveGeneratorStates()
    {
        foreach(var kvp in _randoms)
        {
            var serialized = JsonConvert.SerializeObject(kvp.Value);
            _db.StringSet($"random-generator-state:{kvp.Key}", serialized);
        }
    }

    public void Dispose()
    {
        _redis?.Dispose();
    }
}
```
