["Here is a basic example of how you can structure your Node.js module using Express for routing, Mongoose for data modeling, JSON Web Tokens (JWT) for authentication, and Redis as a cache layer. 

```javascript
const express = require('express');
const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');
const redis = require('redis');

// Connect to MongoDB
mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true });

// Create Redis client
let redisClient;
if (process.env.NODE_ENV === 'production') {
  redisClient = redis.createClient({ url: process.env.REDIS_URL });
} else {
  redisClient = redis.createClient();
}
redisClient.on('error', (err) => console.log(`Redis error: ${err}`));

// Define a schema for user preferences
const UserPreferenceSchema = new mongoose.Schema({
  userId: { type: String, required: true },
  preferences: { type: Map, of: String } // Map to store key-value pairs
});

// Create model from the schema
const UserPreference = mongoose.model('UserPreference', UserPreferenceSchema);

// Middleware for authentication
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization']
  const token = authHeader && authHeader.split(' ')[1]

  if (token == null) return res.sendStatus(401)

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403)
    req.user = user
    next()
  })
}

const app = express();
app.use(express.json()); // for parsing application/json

// Route to get a preference
app.get('/preferences', authenticateToken, async (req, res) => {
  const cacheKey = `preference:${req.user.id}`;
  let preference = await redisClient.get(cacheKey);

  if (!preference) {
    // Fetch from MongoDB and set in Redis for future use
    try {
      preference = await UserPreference.findOne({ userId: req.user.id });
      redisClient.set(cacheKey, JSON.stringify(preference));
    } catch (err) {
      console.error('Error fetching preferences', err);
      return res.status(500).json({ message: 'Failed to fetch preferences' });
    }
  } else {
    // Parse from Redis
    preference = JSON.parse(preference);
  }

  res.json(preference);
});

// Route to update a preference
app.post('/preferences', authenticateToken, async (req, res) => {
  const cacheKey = `preference:${req.user.id}`;

  try {
    // Update MongoDB and invalidate Redis cache
    await UserPreference.findOneAndUpdate({ userId: req.user.id }, req.body, { upsert: true });
    redisClient.del(cacheKey);

    res.json({ message: 'Preferences updated successfully' });
  } catch (err) {
    console.error('Error updating preferences', err);
    return res.status(500).json({ message: 'Failed to update preferences' });
  }
});

// Start server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server running on port ${port}`));
```

Please note that this is a very simplified example. In a real-world application you would need to handle a lot more cases such as validation of user input, proper error handling, security (including encryption), performance optimizations, integration with external services etc. You will also likely need to use some sort of process manager like PM2 or Docker for deployment and scaling purposes.
"]

