// Dynamic MIME Type Validation System
class MimeTypeValidator {
  constructor(policyServer, mimeTypes) {
    this.mimeTypes = mimeTypes;

    setInterval(() => {
      // Fetch the latest policy from server and update mime types
      fetch(policyServer).then((response) => response.json()).then((data) => {
        this.mimeTypes = data.mimeTypes;
      });
    }, 30000); // Update every 30 seconds
  }

  validateMimeType(file, callback) {
    let type = file.type;

    if (!this.mimeTypes[type]) {
      return callback(new Error('Unsupported MIME type'));
    }

    if (file.size > this.mimeTypes[type].maxSize) {
      return callback(new Error('File size limit exceeded'));
    }

    return callback(null, 'Valid MIME type');
  }
}

// Dynamic Pricing Model
class PricingModel {
  constructor() {
    this.prices = {
      basePrice: 0.1,
      pricePerMB: 0.01
    };

    setInterval(() => {
      // Adjust pricing dynamically based on conditions (e.g., network congestion)
      if(networkCongestion()) this.prices.basePrice += 0.05;
    }, 60000); // Update every minute
  }

  calculateCost(files) {
    return files.reduce((total, file) => {
      let size = file.size / (1024 * 1024); // convert bytes to MB

      total += this.prices.basePrice + (this.prices.pricePerMB * size);

      return total;
    }, 0);
  }
}
```

