    private readonly IExternalDataSource dataSource;

    public DynamicUserAccountService(IExternalDataSource dataSource)
    {
        this.dataSource = dataSource;
    }

    public string HandleRequest(string requestJson)
    {
        var request = JsonSerializer.Deserialize<dynamic>(requestJson);

        switch (request?.sub_action?.ToString() ?? "")
        {
            case "create":
                return CreateOrUpdateUser(request).Result;
            case "update":
                return CreateOrUpdateUser(request).Result;
            case "delete":
                return DeleteUser(request).Result;
            default:
                throw new NotImplementedException();
        }
    }

    private async Task<string> CreateOrUpdateUser(dynamic request)
    {
        var id = (request?.id as string);
        var name = (request?.name as string);
        var email = (request?.email as string);
        var password = (request?.password as string);
        var role = (request?.role as string);

        if (string.IsNullOrEmpty(id))
        {
            id = Guid.NewGuid().ToString();
        }

        // Assume that the external data source throws an exception on failure
        await dataSource.SaveUserAsync(new User(id, name, email, password, role));

        return JsonSerializer.Serialize(new { message = "success" });
    }

    private async Task<string> DeleteUser(dynamic request)
    {
        var id = (request?.id as string);

        if (!users.ContainsKey(id))
        {
            return JsonSerializer.Serialize(new { message = "error", details = $"No user found with ID '{id}'." });
        }

        // Assume that the external data source throws an exception on failure
        await dataSource.DeleteUserAsync(id);

        return JsonSerializer.Serialize(new { message = "success" });
    }
}
