public void AddWebsite(string siteName, string directoryPath) {
    // Check if web.config file exists
    var configFilePath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(configFilePath)) {
        return;
    }

    // Add the website to IIS using Process.Start()
    var startInfo = new ProcessStartInfo {
        FileName = "cmd",
        Arguments = $"/c iisreset /add {siteName} /app.name/{directoryPath}"
    };
    Process.Start(startInfo);

    // Wait for IIS to apply changes
