MD5 and SHA-256 Hashing in Python:
```python
import hashlib
BUF_SIZE = 65536  # lets read stuff in 64kb chunks
def getHash(file):
    md5 = hashlib.md5()
    sha256 = hashlib.sha256()

    with open(file, 'rb') as f:
        while True:
            data = f.read(BUF_SIZE)
            if not data:
                break
            md5.update(data)
            sha256.update(data)

    print("MD5: {0}".format(md5.hexdigest()))
    print("SHA256: {0}".format(sha256.hexdigest()))
```
Validating OAuth2 Access Token in C:
```c
#include <stdio.h>
#include <json-c/json.h>
#include <string.h>

int validateAccessToken(const char *accessToken) {
    struct json_object *jobj, *jtoken;
    enum json_tokener_error error;

    jobj = json_tokener_parse(accessToken);
    if (!jobj) {
        fprintf(stderr, "Failed to parse JSON\n");
        return -1;
    }

    /* Verify required fields */
    if (!json_object_object_get_ex(jobj, "access_token", &error)) {
        fprintf(stderr, "'access_token' field is missing\n");
        return -1;
    }

    jtoken = json_object_object_get(jobj, "token_type");
    if (!json_object_is_type(jtoken, json_type_string)) {
        fprintf(stderr, "'token_type' field is missing or not a string\n");
        return -1;
    }

    jtoken = json_object_object_get(jobj, "expires_in");
    if (!json_object_is_type(jtoken, json_type_int)) {
        fprintf(stderr, "'expires_in' field is missing or not an integer\n");
        return -1;
    }

    /* 'refresh_token' is optional */
    jtoken = json_object_object_get(jobj, "refresh_token");
    if (jtoken && !json_object_is_type(jtoken, json_type_string)) {
        fprintf(stderr, "'refresh_token' field is not a string\n");
        return -1;
    }

    /* Access token is valid */
    printf("Access token is valid.\n");
    return 0;
}
```
