        var cachedValue = _database.StringGet($"{serviceName}:{location}");

        if (cachedValue.HasValue) {
            // use the cached value
            Console.WriteLine(cachedValue);
        } else {
            // fetch new data and cache it
            var authRequest = await services[serviceName].AuthFunction();
