```rust
use std::sync::Arc;
use rand::Rng;

pub struct RecordManager {
    offsets: Arc<Vec<u64>>,
    keys: Arc<Vec<i32>>,
}

impl RecordManager {
    pub fn new(size: usize) -> Self {
        let mut rng = rand::thread_rng();

        let offsets: Arc<Vec<u64>> = (0..size).map(|_| rng.gen()).collect();
        let keys: Arc<Vec<i32>> = (0..size).map(|_| rng.gen()).collect();

        Self { offsets, keys }
    }
}
```
