// Function to add a new interface to the system
void add_interface(int id, char *vlan, char *qinq, char *qos, char *ipv6) {
    pthread_mutex_lock(&mutex); // Acquire lock
    interface_t *interface = malloc(sizeof(interface_t)); // Allocate memory for the new interface
    if (interface == NULL) {
        printf("Error: Unable to allocate memory.\n");
        pthread_mutex_unlock(&mutex); // Release lock before returning
        return;
    }
    interface->id = id;
    interface->vlan = strdup(vlan);
    interface->qinq = strdup(qinq);
    interface->qos = strdup(qos);
    interface->ipv6 = strdup(ipv6);

    // Add the new interface to the network
    int network_id = id / 100;
    networks[network_id].interfaces[networks[network_id].interface_count] = interface;
    networks[network_id].interface_count++;

    pthread_mutex_unlock(&mutex); // Release lock after modifying data
}
