```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>

// A simple thread-safe queue for tasks.
template<typename T>
class SafeQueue {
    std::queue<T> q;
    std::mutex mtx;
    std::condition_variable cv;
public:
    void push(const T& value) {
        std::lock_guard<std::mutex> lock(mtx);
        q.push(value);
        cv.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mtx);
        while (q.empty()) {
            cv.wait(lock);
        }
        T value = q.front();
        q.pop();
        return value;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mtx);
        return q.empty();
    }
};

// Example of a health-check function for a file descriptor.
bool checkFileDescriptorHealth(int fd) {
    // Replace this with actual health check logic.
    if (fd < 0) {
        std::cerr << "Invalid file descriptor\n";
        return false;
    }

    return true;
}

// Worker thread function.
void worker(SafeQueue<int>& queue) {
    while (!queue.empty()) {
        int fd = queue.pop();

        if (checkFileDescriptorHealth(fd)) {
            std::cout << "FD: " << fd << " is healthy\n";
        } else {
            std::cerr << "FD: " << fd << " is unhealthy\n";
        }
    }
}

int main() {
    SafeQueue<int> queue;

    // Push some fake file descriptors into the queue.
    for (int i = 0; i < 10; ++i) {
        queue.push(i);
    }

    const int numWorkers = std::thread::hardware_concurrency();
    std::vector<std::thread> workers;

    // Start worker threads.
    for (int i = 0; i < numWorkers; ++i) {
        workers.push_back(std::thread(worker, std::ref(queue)));
    }

    // Join all worker threads.
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
```
This code creates a basic health-check system that checks the health of file descriptors. It uses a `SafeQueue` class to handle concurrent access and ensure each worker is working on different tasks. The actual health check function is just a placeholder, you would replace it with your own logic for checking resource health.

