    AES_KEY* encryption_key;
};
typedef struct aes_context AESContext;

AESContext* create_aes_context(const unsigned char* key, int key_len) {
    AESContext *ctx = malloc(sizeof(AESContext));
    if (!ctx) {
        // Handle error here (e.g., return NULL and propagate upwards)
    }

