// Struct to hold interface details
typedef struct Interface {
    char* name;
    int vlanTagging;
    // Add more fields as needed
} Interface;

Interface** interfaces = NULL;
size_t numInterfaces = 0;

// Lock for thread safety
pthread_mutex_t lock; 

void addInterface(char* name, int vlanTagging) {
    pthread_mutex_lock(&lock);

    // Reallocate memory to store new interface details
    interfaces = realloc(interfaces, (numInterfaces + 1) * sizeof(Interface));
    if (interfaces == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Create a new interface and add it to the array
    Interface* newInterface = malloc(sizeof(Interface));
    newInterface->name = name;
    newInterface->vlanTagging = vlanTagging;
    interfaces[numInterfaces++] = newInterface;

    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize lock
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex init failed\n");
        return 1;
    }

    addInterface("eth0", 1);
    // Add more interfaces here...

    // Cleanup
    for(int i = 0; i < numInterfaces; ++i) {
        free(interfaces[i]);
    }
    free(interfaces);

    pthread_mutex_destroy(&lock);
}
``` 
