```cpp
void ResourceManager::updateResource(const std::string &resourceName, const Json::Value &newConfig) {
    mtx.lock(); // lock mutex to ensure thread safety
    updateQueue.push({resourceName, newConfig}); // add the update to the queue
    applyUpdate(); // try to apply the update
    mtx.unlock(); // unlock mutex
}
```
The `applyUpdate` function would attempt to apply the next update in the queue:
```cpp
bool ResourceManager::applyUpdate() {
    if (updateQueue.empty()) return false;

    auto [resourceName, newConfig] = updateQueue.front();
