double calculate_median(std::vector<int>& data) {
    size_t size = data.size();

    if (size > 1) {
        std::sort(data.begin(), data.end());

        if (size % 2 == 0)
            return static_cast<double>(data[(size / 2) - 1] + data[size / 2]) / 2;
        else
            return static_cast<double>(data[size / 2]);
    }
    return size ? static_cast<double>(data[0]) : 0.0;
}

void process_csv_file(std::string filepath, int divisible_by = 1) {
    std::ifstream input_file(filepath);
    if (!input_file.is_open()) {
        BOOST_LOG_TRIVIAL(error) << "Failed to open CSV file: " + filepath;
        return;
    }

    auto start = std::chrono::high_resolution_clock::now();
    std::vector<int> numbers;
