import yaml
from os import environ as env
import logging

class Configuration:
    def __init__(self):
        self._config = {}

    def load_yaml(self, path):
        with open(path, 'r') as stream:
            try:
                self._config = yaml.safe_load(stream)
            except yaml.YAMLError as exc:
                logging.error(exc)

    def get_config(self):
        return self._config

    def set_environment(self, env_name):
