class DNSResolver:
    def __init__(self):
        # initialize C based component

    def resolve(self, domain):
        return self._resolve(domain)

def make_request(url):
    for api, key in API_KEYS.items():
        resp = requests.get(f"{api}/dns?key={key}", timeout=5)
        if resp.status_code == 200:
            return resp.json()

    raise Exception("All APIs failed")

@app.route('/resolve', methods=['GET'])
def resolve():
    domain = request.args.get('domain')
    # check cache
    if domain in cache:
        return cache[domain]

    data = make_request(domain)
    cache[domain] = data  # update the cache
    return data
```

