import boto3
import google.cloud as gcp
import pandas as pd
from protobuf import * # Assume we have some kind of protobuf library
from requests import get, post
from numpy import mean
from scipy import stats

class RealtimeDataAggregator:
    def __init__(self, cloud_service='AWS', storage_bucket=None, processing_function=mean):
        self.cloud_service = cloud_service
        self.storage_bucket = storage_bucket
        self.processing_function = processing_function

    def handle_data(self, data, format):
        if format == 'JSON':
            return pd.read_json(data)
        elif format == 'CSV':
            return pd.read_csv(data)
        elif format == 'Protobuf':
            # Assume we have a function to decode Protobuf data
            return protobuf_decode(data) 
        else:
            raise ValueError('Unsupported Data Format')

    def process_streams(self, streams):
        for stream in streams:
            data = self.handle_data(stream['data'], stream['format'])
            processed_data = self.processing_function(data)

            if self.cloud_service == 'AWS':
                s3 = boto3.resource('s3')
                s3.Bucket(self.storage_bucket).put_object(Key=stream['name'], Body=processed_data)
            elif self.cloud_service == 'GCP':
                storage_client = gcp.storage.Client()
                bucket = storage_client.get_bucket(self.storage_bucket)
                blob = bucket.blob(stream['name'])
                blob.upload_from_string(processed_data)

    def integrate_third_party(self, url, headers):
        try:
            response = get(url, headers=headers)
            data = response.json()
            processed_data = self.processing_function(data)
            post(url, json=processed_data)
        except Exception as e:
            print('Failed to integrate with third-party API:', str(e))
``` 
This is a basic starting point and only includes the functionality for handling data streams, processing them, and integrating with third party APIs. There are many more features that could be added based on your requirements like customizable aggregation functions, error handling, performance monitoring, user customization, etc. All these would require considerable effort and testing to ensure they work correctly in all scenarios.
