#include "json.hpp"
#include <openssl/sha.h>
#include <cstring>
using json = nlohmann::json;

std::string get_checksum(const std::string& filename) {
    unsigned char c[SHA256_DIGEST_LENGTH];
    SHA256_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    ifstream in(filename, std::ifstream::binary);
    SHA256_Init(&mdContext);
    while ((bytes = in.read((char*)&data, sizeof(data)).gcount() > 0)) {
        SHA256_Update(&mdContext, data, bytes);
    }
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(c, &mdContext);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int) c[i];
    }

    return ss.str();
}

json dirToJson(const char* path, const int depth = 0) {
    json j;
    DIR *dir;
    struct dirent *entry;
    struct stat info;

    if ((dir = opendir(path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            const string file_path = path + "/" + entry->d_name;
            if (stat(file_path.c_str(), &info) != 0) {
                continue;
            }

            json fileJson;
            fileJson["name"] = entry->d_name;
            fileJson["size"] = info.st_size;
            // add other metadata as needed...

            if (S_ISDIR(info.st_mode)) {
                if (strcmp(entry->d_name, "..") != 0 && strcmp(entry->d_name, ".") != 0) {
                    fileJson["contents"] = dirToJson(file_path.c_str(), depth + 1);
                }
            } else if (S_ISREG(info.st_mode)) {
                // add checksum...
                fileJson["checksum"] = get_checksum(file_path);
            }

            j[entry->d_name] = fileJson;
        }
        closedir(dir);
    } else {
        throw runtime_error("Could not open directory");
    }

    return j;
}
``` 
You can use this function by calling `cout << dirToJson("/path/to/directory")`. This is a simple example and does not include error handling for different types of errors such as permission denied, invalid path etc. For real-world usage, you should add these checks and handle them according to the requirements of your application. 

