using System;
using System.IO;
using System.Net;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;
using ProtoBuf;

public class WorldConfigurator
{
    private readonly ILogger<WorldConfigurator> _logger;
    private readonly IWebServiceClient _webServiceClient;
    private readonly IConfiguration _configuration;

    public WorldConfigurator(ILogger<WorldConfigurator> logger, IWebServiceClient webServiceClient, IConfiguration configuration)
    {
        _logger = logger;
        _webServiceClient = webServiceClient;
        _configuration = configuration;
    }

    public async Task LoadFromFileAsync(string filePath)
    {
        try
        {
            using (var streamReader = new StreamReader(filePath))
            {
                var content = await streamReader.ReadToEndAsync();

                if (filePath.EndsWith(".json"))
                    LoadFromJson(content);
                else if (filePath.EndsWith(".proto"))
                    LoadFromProtoBuf(content);
                else
