const express = require('express');
const fetch = require('node-fetch');
const redis = require('redis');
const client = redis.createClient();
const app = express();
app.use(express.json());

// Configure your external currency API here
const EXTERNAL_API_URL = `https://externalapi.com/endpoint?base=USD&symbols=EUR,GBP`;

client.on('error', (err) => console.log(`Error ${err}`));

// Middleware to check cache before hitting external API
const checkCache = async (req, res, next) => {
  const base_currency = req.params.base_currency;
  client.get(base_currency, (error, result) => {
    if (error) throw error;
    if (result !== null) {
      res.send({
        fromCache: true,
        data: JSON.parse(result),
      });
    } else next(); // Go to external API if not in cache
  });
};

app.get('/currency/:base_currency', checkCache, async (req, res) => {
  const base_currency = req.params.base_currency;

  try {
    const response = await fetch(`${EXTERNAL_API_URL}&base=${base_currency}`);
    const data = await response.json();

    // Save to Redis Cache and set expiration (e.g., 5 minutes)
    client.setex(base_currency, 300, JSON.stringify(data));

    res.send({
      fromCache: false,
      data: data,
    });
  } catch (error) {
    console.log(error);
    res.status(500).send('Server error');
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```
This code creates an Express server that responds to GET requests at the `/currency/:base_currency` endpoint. It first checks if the requested currency conversion rates are in Redis cache (a fast, persistent storage system), and returns them if they're available. If not, it fetches them from an external API, saves them in the cache for 5 minutes, and sends them to the client.

