```javascript
function copyBytes(buffers, length) {
  let totalLength = 0;

  for (let buffer of buffers) {
    totalLength += buffer.length;
  }

  if (totalLength < length) {
    throw new Error('Not enough data to copy');
  }

  const result = Buffer.allocUnsafe(length);

  let pos = 0;

  for (let buffer of buffers) {
    let bytesToCopy = Math.min(buffer.length, length - pos);

    buffer.copy(result, pos, 0, bytesToCopy);
    pos += bytesToCopy;

    if (pos >= length) {
      break;
    }
  }

  return result;
}
```
This function takes a list of buffers and copies a specified number of bytes from these buffers into a new buffer, ensuring that it does not modify the original data. It throws an error if there is not enough data to copy.

