    const response = await IstioClient.callService(SERVICE_NAME);
    res.json({response});
  } catch (error) {
    res.status(500).send('Error while calling service');
  }
});

// Rate limiting middleware based on user role, service health and geographic distribution
const rateLimiter = new Prometheus.Rate({
  name: 'request_rate',
  help: 'Request rate per minute',
  labelNames: ['userRole', 'serviceName', 'geoLocation'],
});

app.use((req, res, next) => {
  // Get user role and service from the database based on the request
  const userRole = getUserRole(req);
  const serviceName = getServiceName(req);
  const geoLocation = req.ip;

  const numOfRequests = rateLimiter.get({userRole, serviceName, geoLocation});
  if (numOfRequests > 100) { // Adjust this number based on your needs
    res.status(429).send('Too Many Requests');
  } else {
    next();
  }
});

// Monitoring and logging middleware with Prometheus, Grafana
const httpRequestDurationMicroseconds = new Prometheus.Histogram({
  name: 'http_request_duration_ms',
  help: 'Duration of HTTP requests in ms',
  labelNames: ['method', 'route', 'code'],
  buckets: [0.10, 5, 15, 50, 100, 200, 300, 400, 500]
})

app.use((req, res, next) => {
  const end = httpRequestDurationMicroseconds.startTimer();

  res.on('finish', () => {
    end({ route: req.route.path, code: res.statusCode, method: req.method });
  })
  next()
})

// Jaeger distributed tracing system
const initTracer = (serviceName) => {
  const config = {
    serviceName: serviceName,
    sampler: {
      type: "const",
      param: 1,
    },
    reporter: {
      logSpans: true,
    },
  };
  const options = {
    tags: {
      'my-app.version': '0.0.1',
    },
  };
  return Jaeger.initTracer(config, options);
};

// Self-healing mechanism
app.use((err, req, res, next) => {
  console.error('An error occurred: ', err.stack);
  // Add code here to trigger a self-healing procedure if the error is due to service failure or network issues
});

app.listen(process.env.PORT || 3001, () => console.log("Server running on port 3001"));
```

