["This is a complex task which cannot be fully implemented in this context due to complexity of the requirements mentioned above. However, I can provide you an example of how you could start building a basic key-value store with thread safety and adaptive eviction strategy. 

```cpp
#include <list>
#include <unordered_map>
#include <shared_mutex>

template<typename K, typename V>
class Cache {
private:
    struct ValueWithTTL {
        V value;
        std::time_t timestamp;
        int ttl;  // Time to live in seconds.

        ValueWithTTL(const V& value, int ttl) : value(value), timestamp(std::time(0)), ttl(ttl) {}
    };

    struct Record {
        std::shared_ptr<ValueWithTTL> val;
        typename std::list<K>::iterator itr;  // Iterator in the LRU list.
    };

    mutable std::shared_mutex mtx_;
    size_t capacity_;  // Cache capacity.
    std::unordered_map<K, Record> map_;
    std::list<K> lruList_;  // Least recently used keys.

public:
    explicit Cache(size_t capacity) : capacity_(capacity) {}

    void Put(const K& key, const V& value, int ttl = 0) {
        std::unique_lock<std::shared_mutex> lock(mtx_);

        if (map_.find(key) == map_.end()) {
            // Evict LRU if needed.
            if (lruList_.size() >= capacity_) {
                EraseLRU();
            }
        } else {
            lruList_.erase(map_[key].itr);  // Remove from existing position.
        }

        // Update timestamp and add to front of LRU list.
        ValueWithTTL val(value, ttl);
        map_[key] = {std::make_shared<ValueWithTTL>(val), lruList_.insert(lruList_.begin(), key)};
    }

    std::optional<V> Get(const K& key) const {
        std::shared_lock<std::shared_mutex> lock(mtx_);

        auto itr = map_.find(key);
        if (itr == map_.end()) return {};  // Not found.

        auto now = std::time(0);
        if (itr->second.val->ttl > 0 && now - itr->second.val->timestamp > itr->second.val->ttl) {
            return {};  // Expired.
        }

        lruList_.erase(itr->second.itr);  // Remove from current position.

        itr->second.itr = lruList_.insert(lruList_.begin(), key);  // Add to front of LRU list.
        return itr->second.val->value;
    }

private:
    void EraseLRU() {
        map_.erase(lruList_.back());  // Remove from both map and LRU list.
        lruList_.pop_back();
    }
};
```
This is a basic cache where you can put key-value pairs into the cache with optional TTL (time to live) settings. If a key exists, it updates its position in LRU order and refreshes its timestamp if there's TTL set for the value. When getting, it checks if the value is expired or not by comparing current time with its timestamp and TTL.
"]

