using json = nlohmann::json;
namespace ip = boost::asio::ip;

class ConnectionManager {
    using timestamp_t = std::chrono::time_point<std::chrono::system_clock>;
    struct ConnectionDetails {
        std::string id;
        timestamp_t lastSeen;
        int priorityScore;
        size_t activityCount; // number of times updated in the last minute

        json toJson() const {
            return {{"id", id}, {"lastSeen", std::chrono::system_clock::to_time_t(lastSeen)}, 
                {"priorityScore", priorityScore}, {"activityCount", activityCount}};
        }

        static ConnectionDetails fromJson(const json& j) {
            return {j["id"], timestamp_t(std::chrono::seconds(j["lastSeen"])), 
                j["priorityScore"], j["activityCount"]};
        }
    };

    std::vector<ConnectionDetails> connections;
    mutable std::mutex mtx; // for thread-safety

public:
    void addConnection(std::string id, int priority) {
        std::lock_guard<std::mutex> lock(mtx);
        connections.push_back({id, std::chrono::system_clock::now(), priority, 0});
    }

    void removeConnection(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto newEnd = std::remove_if(connections.begin(), connections.end(), 
            [&](const ConnectionDetails& conn){ return conn.id == id; });
        connections.erase(newEnd, connections.end());
    }

    void updateConnection(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        for(auto& connection : connections) {
