```

`Character.cpp`
```cpp
#include "Character.h"

// Initialize member variables
Character::Character() : 
m_lastExecutedAttack(-1),
m_consecutiveSameAttacks(0) { }

Character::~Character(){
    for(auto& strategy : m_attackStrategies){
        delete strategy;
    }
}

void Character::setAttackStrategies(std::vector<AttackStrategy*>& strategies) { 
    m_attackStrategies = std::move(strategies); 
}

// Check if attack is allowed based on cooldown and consecutive attack limit
bool Character::canExecuteAttack(int attackId, std::chrono::duration<double> elapsedTime) {
    // Ensure that the attack has cooled down
    auto timeSinceLastAttack = std::chrono::system_clock::now() - m_lastAttackTime;
    if (timeSinceLastAttack < m_attackStrategies[attackId]->getCooldown()) { 
        return false; 
    }

    // If the last executed attack is the same as the current one, check for consecutive limit
    if(m_lastExecutedAttack == attackId) {
        ++m_consecutiveSameAttacks;
        if (m_consecutiveSameAttacks > 3){ 
            return false; 
        }
    } else { // reset consecutive attacks counter
        m_consecutiveSameAttacks = 0;
    }

    return true;
}

void Character::executeNextAttack() {
    int bestAttackId = -1;
