#include <thread>
#include <vector>
#include <queue>

std::mutex mtx; // mutex for critical section
std::condition_variable cv;
std::queue<int> buffer; 
const unsigned int buffSize = 1024; 

void producer() {
    while(true) {
        std::vector<int> data = getData(); // function to fetch data from API or wherever it comes from
        std::unique_lock<std::mutex> lck(mtx);
        cv.wait(lck, [](){return buffer.size() < buffSize;});
        for (auto& item : data) {
            buffer.push(item);
        }
        lck.unlock();
        cv.notify_all();
    }
}

void consumer() {
    while(true) {
        std::unique_lock<std::mutex> lck(mtx);
        cv.wait(lck, [](){return buffer.size() > 0;}); 
        int data = buffer.front(); // get the data from buffer
        buffer.pop(); // remove from buffer
        processData(data); // function to process this data
        lck.unlock();
        cv.notify_all();
    }
}
```
