```java
import java.util.*;
import java.time.*;
import org.springframework.web.bind.annotation.*;

@RestController
public class SessionManagementController {
    private final DistributedKVStore store;
    private final AnalyticsAPI analyticsAPI;
    private final MessageQueue messageQueue;

    public SessionManagementController(DistributedKVStore store, AnalyticsAPI analyticsAPI, MessageQueue messageQueue) {
        this.store = store;
        this.analyticsAPI = analyticsAPI;
        this.messageQueue = messageQueue;
    }

    @PostMapping("/sessions")
    public Session startSession(@RequestBody User user) {
        Instant now = Instant.now();
        Session session = new Session(user, now);

        store.write("session:" + session.getId(), session);
        analyticsAPI.sendEvent("start_session", user.getUserId());
        messageQueue.publish("new_session", session);

        return session;
    }

    @DeleteMapping("/sessions/{id}")
    public void endSession(@PathVariable String id) {
        Session session = store.read("session:" + id);
        analyticsAPI.sendEvent("end_session", session.getUser().getUserId());
        messageQueue.publish("end_session", session);

        store.delete("session:" + id);
    }

    @GetMapping("/sessions/{id}")
    public Session getSession(@PathVariable String id) {
        return store.read("session:" + id);
    }
}
```
This code is for the RESTful endpoints to start, end and query sessions. It uses `DistributedKVStore`, `AnalyticsAPI` and `MessageQueue` which are placeholders for actual dependencies. The methods use these dependencies to store session data, send events to analytics API and publish messages to message queue respectively.

