}
```

Next, the `IDataAccessLayer` interface:

```csharp
public interface IDataAccessLayer : IDisposable
{
    Task<IEnumerable<TEntity>> ExecuteSqlQueryAsync<TEntity>(string sqlQuery) where TEntity : class;
}
```

The `DataAccessLayer`:

```csharp
public class DataAccessLayer : IDataAccessLayer
{
    private readonly MyDbContext _context;

    public DataAccessLayer(MyDbContext context) 
    {
        this._context = context;
    }

    public async Task<IEnumerable<TEntity>> ExecuteSqlQueryAsync<TEntity>(string sqlQuery) where TEntity : class
    {
        return await _context.Set<TEntity>().FromSqlRaw(sqlQuery).ToListAsync();
    }

    public void Dispose() => _context?.Dispose();
}
```

You can use this as follows:

```csharp
