{
    using var dataAccessLayer = new DataAccessLayer(new MyDbContext(options)); // Replace options with actual options

    string sqlQuery = "SELECT * FROM MyTableEntities"; // You can use your dynamic SQL here
    IEnumerable<MyTableEntity> entities = await dataAccessLayer.ExecuteSqlQueryAsync<MyTableEntity>(sqlQuery);
}
```
