    public ResponseEntity<String> createResource(@RequestBody String resourceData) {
        try{
            String resourceId = generateUniqueID(); //generate unique ID for the resource
            producer.send(new ProducerRecord<>("resource_topic", resourceId, resourceData)); //asynchronous processing 
            jedis.set(resourceId, "INPROGRESS"); //in progress status in Redis cache

            return new ResponseEntity<String>("Resource created with ID: "+resourceId, HttpStatus.CREATED);
        } catch (Exception e) {
            e.printStackTrace();
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }

    @PutMapping("/resource/{id}")
    public ResponseEntity<String> updateResource(@PathVariable String id, @RequestBody String resourceData) {
        try{
            if(!jedis.exists(id)){ //Check if the resource exists 
                return new ResponseEntity<>("Resource not found", HttpStatus.NOT_FOUND);
            }

            jedis.set(id, "INPROGRESS"); //Set status as INPROGRESS in Redis cache
            producer.send(new ProducerRecord<>("resource_topic", id, resourceData)); //asynchronous processing 

            return new ResponseEntity<String>("Resource updated with ID: "+id, HttpStatus.OK);
        } catch (Exception e) {
            e.printStackTrace();
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }

    //Similarly implement delete and get resource methods 

