import org.redisson.config.Config;

public class ResourceManager {
    private final RedissonClient redisson = getRedisson();

    public void updateResource(String id, Object payload) throws Exception {
        RLock lock = redisson.getLock("resource-lock-" + id);

        boolean isAcquired = lock.tryLock(100, 10, TimeUnit.SECONDS);

        if (isAcquired) {
            try {
                // Perform update operation here
            } finally {
                lock.unlock();
            }
        } else {
            throw new RuntimeException("Unable to acquire lock for resource " + id);
        }
    }

    private RedissonClient getRedisson() {
        Config config = new Config();
        // Configure redisson here 

        return Redisson.create(config);
    }
}
