public class Startup
{
    public IConfiguration Configuration { get; }

    public Startup(IConfiguration configuration) => Configuration = configuration;

    public void ConfigureServices(IServiceCollection services)
    {
        // Register dependencies and configurations
        services.AddHttpClient();
        services.AddSingleton<PolicyRegistry>();
        services.Configure<ExternalServiceConfig>(Configuration.GetSection("ExternalService"));
        services.AddScoped<IDynamicUserAccountRepository, DynamicUserAccountRepository>();
        services.AddScoped<IDynamicUserAccountService, DynamicUserAccountService>();
    }
}

