    private SomeDataSource dataSource;

    // We use a Message Broker (Kafka/RabbitMQ) to push data 
    private MessageBroker messageBroker;

    public void ingestData() {
        while(true) {
            Object data = dataSource.getData();
            if (data != null) {
                // serialize data into byte array or string depending on protocol you choose
                String serializedData = serialize(data); 

