    // Implement this using Facebook's SDK
}

interface UserRepositoryInterface {
    public function find($id);
    // Other methods as needed...
}

class UserService {
    private $userRepo;
    private $externalServices = [];

    public function __construct(UserRepositoryInterface $userRepo, array $externalServices) {
        $this->userRepo = $userRepo;
        foreach ($externalServices as $service) {
            if (!$service instanceof ExternalAuthInterface) {
                throw new InvalidArgumentException('All services must implement ExternalAuthInterface');
            }
            $this->externalServices[] = $service;
        }
    }

    public function authenticate(array $credentials, $provider = null) {
        if ($provider) {
            // Try to authenticate with a specific provider
            foreach ($this->externalServices as $service) {
                if (get_class($service) === $provider) {
                    return $service->authenticate($credentials);
                }
            }
        } else {
            // Try to authenticate with all providers
            foreach ($this->externalServices as $service) {
                $result = $service->authenticate($credentials);
                if ($result) {
                    return $result;
                }
            }
        }

        // If no provider is provided or all providers failed, authenticate locally
        $user = $this->userRepo->findByEmail($credentials['email']);
        if (!$user || !password_verify($credentials['password'], $user->getPasswordHash())) {
            throw new AuthenticationException('Invalid credentials');
        }

        return $user; // Assuming a User object is returned on successful authentication
    }

    public function changePassword(User $user, $oldPassword, $newPassword) {
        if (!password_verify($oldPassword, $user->getPasswordHash())) {
            throw new InvalidArgumentException('Invalid old password');
        }

        $user->setPassword($newPassword); // Implement this to hash and store the new password
        $this->userRepo->save($user);
    }

    public function sendResetEmail(User $user) {
        // Generate a unique token, save it in a cache or database for later validation
        $resetToken = bin2hex(random_bytes(16)); 
        $this->cacheService->save('password_reset:' . $resetToken, $user->getId(), 'EX', 3600); // One hour TTL

        // Send the email with a link containing the token to reset the password
    }
}
```
In this example, each external service is responsible for its own authentication. The UserService tries to authenticate locally by default, but if a specific provider is provided or all providers fail, it falls back to local authentication using email and password stored in the database. The password is hashed and salted before being saved in the database to further increase security.

Please note that this is just an example and real-world implementation might be much more complex considering error handling, user input validation, rate limiting, caching strategies, logging and monitoring tools integration, etc.
