["This task is quite complex and beyond the capacity of a language model like me to provide a complete code block for such a task. However, I can sketch out an outline for how you might approach this problem using NodeJS with OpenSSL library and supporting tools/libraries such as async/await, dotenv (for handling environment variables), winston (for logging) etc.:

```javascript
const crypto = require('crypto');
const pbkdf2 = require('pbkdf2');
const OpenSSL = require('openssl-nodejs'); // hypothetical node.js openssl wrapper
require('dotenv').config();
const winston = require('winston');

// Define logger
const logger = winston.createLogger({ /* add logging configuration here */ });

class EncryptionService {
  constructor() {
    this.encryptionContexts = new Map();
  }

  async enableEncryption(userId, password) {
    const salt = crypto.randomBytes(16); // for PBKDF2
    const derivedKey = await pbkdf2.pbkdf2Sync(password, salt, parseInt(process.env.PBKDF2_ITERATIONS), 32, 'sha256');

    this.encryptionContexts.set(userId, { key: derivedKey, iv: crypto.randomBytes(16) });

    // Securely erase password from memory
    for (let i = 0; i < password.length; i++) {
      password[i] = 0x00;
    }
  }

  disableEncryption(userId) {
    const context = this.encryptionContexts.get(userId);

    if (context) {
      // Securely erase key and IV from memory
      for (let i = 0; i < context.key.length; i++) {
        context.key[i] = 0x00;
      }

      for (let i = 0; i < context.iv.length; i++) {
        context.iv[i] = 0x00;
      }

      this.encryptionContexts.delete(userId);
    } else {
      logger.warn('Attempted to disable encryption for non-existent user');
    }
  }

  async encryptData(userId, data) {
    const context = this.encryptionContexts.get(userId);

    if (!context) {
      logger.error('Encryption is not enabled for the given user');
      throw new Error('Encryption is not enabled for the given user');
    }

    // Encrypt using OpenSSL and AES-256-GCM
    const encryptedData = await OpenSSL.aes_encrypt(data, context.key, { iv: context.iv });

    return encryptedData;
  }

  async decryptData(userId, data) {
    const context = this.encryptionContexts.get(userId);

    if (!context) {
      logger.error('Decryption is not enabled for the given user');
      throw new Error('Decryption is not enabled for the given user');
    }

    // Decrypt using OpenSSL and AES-256-GCM
    const decryptedData = await OpenSSL.aes_decrypt(data, context.key, { iv: context.iv });

    return decryptedData;
  }

  // add other methods as per requirements (e.g., cleanup method for securely deleting keys)
}
```
The code above is a basic skeleton and needs further development to handle edge cases, error handling, high concurrency, logging, memory usage optimization etc. As cryptography requires careful consideration of security implications and proper implementation can be complex due to its sensitive nature, always follow best practices for secure coding and use trusted libraries where possible.
"]

