       try{ 
           lock.lock();  // Use optimistic locking and version control to ensure atomic updates
           UserProfile profile = db.getUserProfile(userId);
           if (profile != null){
               int oldVersion = profile.version;
               profile.updateFields(updatedFields);  // Update only the necessary fields, no need for a complete replace operation
               db.putUserProfile(userId, updatedProfile); 

               if (oldVersion == updatedProfile.version) {
                   // Successful update, update cache and analytics service
                   cache.update(userId, updatedProfile);
                   analyticsService.updateUserProfile(updatedProfile);

               } else {
                   throw new Exception("Data has been modified since last read, please try again."); 
                // Handle version conflict
               }
           }
       } finally{
           lock.unlock();
       }
    }

