import asyncio
import logging
from collections import deque

class RealtimeStreamProcessor:
    def __init__(self, filter_functions, transform_functions, dedupe_function):
        self.filter_functions = filter_functions
        self.transform_functions = transform_functions
        self.dedupe_function = dedupe_function
        self.data_history = deque(maxlen=100)  # Rolling history of processed data

    async def consume_api_streams(self, api_list):
        tasks = []
        for api in api_list:
            task = asyncio.ensure_future(self._consume_api_stream(api))
            tasks.append(task)

        await asyncio.gather(*tasks)  # Concurrent execution of API streams

    async def _consume_api_stream(self, api):
        try:
            while True:
                data = await self._fetch_data(api)  # Assuming this function exists to fetch data from the API

                for func in self.filter_functions:
                    data = func(data)

                for func in self.transform_functions:
                    data = func(data)

                if not self.dedupe_function(data, self.data_history):  # Skip duplicates
                    continue

                self.data_history.append(data)
        except Exception as e:
            logging.error('Failed to consume API stream', exc_info=e)

