package main

import (
	"sync"
	"time"
)

type StreamCompressor struct {
	cache   sync.Map // Use a thread-safe Map for caching compressed data
	channel chan string
}

func NewStreamCompressor() *StreamCompressor {
	c := &StreamCompressor{
		channel: make(chan string),
	}
	go c.compressLoop() // Start a separate goroutine for compression loop
	return c
}

func (c *StreamCompressor) Compress(data string) {
	c.channel <- data // Send the data to the channel, which will be consumed by compressLoop in another goroutine
}

func (c *StreamCompressor) compressLoop() {
	for data := range c.channel {
		// Code to compress data goes here
		cachedData, found := c.cache.Load(data) // Check if the data is already in cache
		if !found {
			compressedData := compress(data) // Assume this function exists to compress the data
			c.cache.Store(data, compressedData) // Store the result in cache
			// Code to send compressed data goes here
		} else {
			// Use cached data if it's found
			compressedData := cachedData.(string)
			// Code to send compressed data goes here
		}
	}
}
```

