typedef struct MemoryPool {
    size_t capacity;
    NetworkInterface** interfaces;
} MemoryPool;

MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->capacity = capacity;
    pool->interfaces = (NetworkInterface**) calloc(capacity, sizeof(NetworkInterface*));
    if (pool->interfaces == NULL) {
        free(pool);
        return NULL;
    }

    return pool;
}

NetworkInterface* create_network_interface(const char* ip_address, const char* mac_address) {
    NetworkInterface* nic = (NetworkInterface*) malloc(sizeof(NetworkInterface));
    if (nic == NULL) return NULL;

    // Copy the ip and mac addresses to the new memory location
    nic->ip_address = strdup(ip_address);
    nic->mac_address = strdup(mac_address);

    return nic;
}

int add_to_memory_pool(MemoryPool* pool, NetworkInterface* interface) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->interfaces[i] == NULL) {
            pool->interfaces[i] = interface;
            return 1; // success
        }
    }

    return 0; // failure, no free slots in the memory pool
}
```
