class AuthModule(object):
    def __init__(self, config):
        self.config = config
        self.endpoints = {}

    async def get_token(self, provider):
        if not self.endpoints[provider].is_healthy():
            await self.switch_endpoint()

        return await self.endpoints[provider].get_token()

    async def switch_endpoint(self):
        for endpoint in self.endpoints:
