['Here is a simple example of how you could design your Rust application. Note that this code will require additional implementation details from your side, such as API endpoints, request/response formats, error handling, file I/O, etc. Also please note that the below code assumes that there's an `async_fetch_settings()` function to fetch configuration settings from external API and a `apply_transformations()` function to apply transformations on data read from binary files.

```rust
use tokio::fs::{self, File};
use tokio::sync::Mutex;
use tokio::runtime::Handle;
use futures::stream::StreamExt;

#[tokio::main]
async fn main() {
    let mut rt = Handle::current();

    // Get configuration settings from external API.
    let config = async_fetch_settings().await.unwrap_or_else(|e| panic![{:?}, e]);

    // Open binary file for reading
    let mut input_file = File::open("input.bin").await.unwrap();

    // Create output file
    let mut output_file = fs::File::create("output.txt").await.unwrap();

    // Read from the binary file asynchronously
    let read_stream = tokio::fs::read(&input_file);

    // Apply transformations to data from stream and write to output file
    rt.block_on(apply_transformations(config, read_stream, &mut output_file))
}

async fn apply_transformations(config: Config, mut stream: tokio::fs::ReadDirStream, mut output_file: fs::File) {
    let mut lock = Mutex::new(output_file);

    // Process each chunk of data in a separate task. 
    // This will allow concurrent processing for large files.
    stream.for_each_concurrent(32, |chunk| async move {
        let mut file = lock.lock().await;

        match apply_transformations(&config, &chunk?) {
            Ok(result) => tokio::fs::write(file, result).await.unwrap(),

            Err(e) => println![{:?}, e],
        }
    })
    .await;
}
```

