```java
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cloud.stream.messaging.Processor;
import org.springframework.http.HttpStatus;
import org.springframework.messaging.MessageChannel;
import org.springframework.messaging.support.MessageBuilder;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

@Service
public class StreamObserverImpl implements StreamObserver<String> {
    private final MessageChannel output;
    private final KafkaTemplate<String, String> kafkaTemplate;
    private final String topicName;

    @Autowired
    public StreamObserverImpl(@Output(Processor.OUTPUT) MessageChannel channel, 
                              KafkaTemplate<String, String> kafkaTemplate,
                              @Value("${spring.cloud.stream.bindings.output.destination}") String topicName){
        this.output = channel;
        this.kafkaTemplate = kafkaTemplate;
        this.topicName = topicName;
    }

    @Override
    public void onNext(String value) {
        try{
            ProducerRecord<String, String> record = 
                new ProducerRecord<>(topicName, value);
            ListenableFuture<SendResult<String, String>> future = kafkaTemplate.send(record);

            // You may want to add some error handling here for failed sends
            future.addCallback(result -> {
                System.out.println("Sent message: " + value 
                    + ", offset: " + result.getRecordMetadata().offset());
            }, ex -> {
                System.err.println("Failed to send message: " + value);
                throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, ex.getMessage(), ex);
            });
        } catch (Exception e) {
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, e.getMessage(), e);
        }
    }

    @Override
    public void onError(Throwable t) {
        System.out.println("Encountered error: " + t);
    }

    @Override
    public void onCompleted() {
        System.out.println("Finished processing stream.");
    }
}
```

