typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void populateNfapiPduList(int N) {
    for (int i = 0; i < N; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }

        // validate and set values for RX_UE_INFORMATION_TAG and RNTI here...

        pthread_mutex_lock(&lock);
        newNode->next = head;
        head = newNode;
        pthread_mutex_unlock(&lock);
    }
}

void iterateAndUpdate(int criteria) {
    Node* current = head;

    while (current != NULL) {
        // update CRCFLAG based on criteria here...

        current = current->next;
    }
}

void cleanup() {
    pthread_mutex_lock(&lock);
    Node* current = head;

    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    head = NULL;
    pthread_mutex_unlock(&lock);
}
```
