['This task is complex as it involves several areas such as image processing, metadata extraction, system integration, error handling, resource management etc. Writing this in a single C++ function without any additional context will be very difficult and inefficient. 

However, here's an outline of how you might approach implementing each of these features:

1. Quality Assessment: You could use a third-party library such as OpenCV for image processing tasks. You can use the PSNR (Peak Signal to Noise Ratio) or SSIM (Structural Similarity Index Measure) metrics to evaluate the quality of an image. 

```cpp
#include "opencv2/highgui/highgui.hpp"
#include "opencv2/imgproc/imgproc.hpp"
using namespace cv;
double getPSNR(const Mat& I1, const Mat& I2) {
    Mat s1;
    absdiff(I1, I2, s1);       // |I1 - I2|
    s1.convertTo(s1, CV_32F);  // cannot make a square on 8 bits
    s1 = s1.mul(s1);           // |I1 - I2|^2
    Scalar s = sum(s1);        // sum elements per channel
    double sse = s.val[0] + s.val[1] + s.val[2];  // sum channels
    if (sse <= 1e-10)  // for small values return zero
        return 0;
    else {
        double mse = sse / (double)(I1.channels() * I1.total());
        double psnr = 10.0 * log10((255 * 255) / mse);
        return psnr;
    }
}
