class SessionManager {
    std::unordered_map<int, SESSION_STATE_TRANSITION_RECORD> stateMap; // map to store session records
    std::mutex mtx; // mutex for thread synchronization
public:
    void manageSessionStateTransitions(int clientId, const SESSION_STATE_TRANSITION_RECORD& record) {
        std::lock_guard<std::mutex> lock(mtx); // acquire lock on the map

        if (stateMap.find(clientId) == stateMap.end()) { // client not found in map
            stateMap[clientId] = record; 
