    // Format the message string from the arguments
    char message[1024];  // Make this dynamic based on expected log size
    vsprintf(message, fmt, args);

    // Create a new log record with the formatted message and other necessary data
    log_record_t *record = malloc(sizeof(log_record_t));
    record->level = level;
    record->message = message;  // Make this dynamic based on expected log size

