    char* sib;
    pthread_mutex_t lock;
} LTE_RRC_UE_CONTEXT_T;

LTE_RRC_UE_CONTEXT_T* createContext(int ueId, const char* sib) {
    LTE_RRC_UE_CONTEXT_T* context = malloc(sizeof(LTE_RRC_UE_CONTEXT_T));

    if (context == NULL) {
        // handle memory allocation failure
        return NULL;
    }

    context->ueId = ueId;
    context->sib = malloc(strlen(sib) + 1);
    strcpy(context->sib, sib);

    if (pthread_mutex_init(&context->lock, NULL) != 0) {
        // handle mutex initialization failure
        free(context->sib);
        free(context);
        return NULL;
    }

    return context;
}

void updateContext(LTE_RRC_UE_CONTEXT_T* context, const char* sib) {
    pthread_mutex_lock(&context->lock);

    free(context->sib);
    context->sib = malloc(strlen(sib) + 1);
    strcpy(context->sib, sib);

    pthread_mutex_unlock(&context->lock);
}

void deleteContext(LTE_RRC_UE_CONTEXT_T* context) {
    pthread_mutex_destroy(&context->lock);
    free(context->sib);
    free(context);
}
