namespace beast = boost::beast; 
namespace http = beast::http;   
namespace net = boost::asio;  
using tcp = net::ip::tcp;       

class HttpClient {
public:
    void SendRequest(const std::string& host, const std::string& port, const std::string& target) {
        try {
            net::io_context ioc;
            beast::tcp_stream stream(ioc);

            tcp::resolver resolver(ioc);
            beast::tcp_stream sock(ioc);
            auto const results = resolver.resolve(host, port);
            stream.connect(results);
            http::request<http::string_body> req{http::verb::get, target, 10};
            req.set(http::field::host, host);
            req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
            http::write(stream, req);

            beast::flat_buffer buffer;
            http::response<http::dynamic_body> res;
            http::read(stream, buffer, res);

            std::cout << "Response status: " << res.result_int() << "\n";
        } catch (std::exception const& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }
};
```
