const queue = [];
let isProcessing = false;

async function processQueue() {
  if (isProcessing) return; // do nothing until current processing finishes

  const item = queue.shift();
  if (!item) return; // do nothing when queue is empty

  try {
    isProcessing = true;
    await logToExternalService(item);
  } catch (e) {
    queue.unshift(item); // re-add to the front of the queue for retry later
  } finally {
    isProcessing = false;
    processQueue(); // recursively call this function
  }
}
```
4. Implement error handling and retry mechanisms using axios:

