  try {
    await axios.post('https://external-logging-service/log', item);
    retryCount = 0; // reset count after successful attempt
  } catch (e) {
    if (retryCount++ < RETRY_COUNT) {
      console.error(`Error logging to external service, retrying...`);
      return logToExternalService(item); // recursively call this function
    } else {
