However, I can provide you with an example of how you could start implementing such library using C99 standard, including usage of pthread mutexes and conditional variables for thread safety control:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct FrameMetaData {
    double timestamp;
    int frequency;
    char modulation_type[20];
    float signal_strength;
    void* additional_metadata;  // Points to external metadata
} FrameMetaData;

// Comparator for sorting based on signal strength and timestamp
int comparator(const void *a, const void *b) {
    FrameMetaData *f1 = (FrameMetaData *)a;
    FrameMetaData *f2 = (FrameMetaData *)b;

    // Sort by signal_strength first, then by timestamp
    if(f1->signal_strength != f2->signal_strength) {
        return (f1->signal_strength > f2->signal_strength) - (f1->signal_strength < f2->signal_strength);
    } else if(f1->timestamp != f2->timestamp) {
        return (f1->timestamp > f2->timestamp) - (f1->timestamp < f2->timestamp);
    }

    return 0;
}

// Linked list node for FrameMetaData
typedef struct Node {
    FrameMetaData* frame_data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
Node* head = NULL;  // Start of list
int list_size = 0;

void add_frame(FrameMetaData* frame) {
    Node* new_node = malloc(sizeof(Node));

    if(!new_node) {
        return;
    }

    new_node->frame_data = frame;

    pthread_mutex_lock(&lock);
    list_size++;

    // Add the new node at the beginning of the list
    new_node->next = head;
    head = new_node;

    qsort(head, list_size, sizeof(Node), comparator);  // Sort linked list

    pthread_cond_signal(&cond);  // Wake up any waiting thread
    pthread_mutex_unlock(&lock);
}

void delete_frame(FrameMetaData* frame) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev;

    // If the head node itself holds the key to be deleted
    if (temp != NULL && temp->frame_data == frame) {
        head = temp->next;  // Changed head
        free(temp);         // Free old head
        list_size--;
        return;
    }

    // Search for the key to be deleted, keep track of the previous node as we need to change 'prev->next' */
    while (temp != NULL && temp->frame_data != frame) {
        prev = temp;
        temp = temp->next;
    }

    // If key was not present in linked list
    if (temp == NULL) return;

    // Unlink the node from linked list 
    prev->next = temp->next;

    free(temp);  // Free memory

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}
```
Please note that this is a simplified example and may not be production ready. It doesn't include many features such as error checking, robustness against all possible failures or more advanced memory management strategies. Also, the provided code for adding and removing frames does not handle edge cases properly (e.g., when list is empty).
"]

