```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

template<typename T>
class Stream {
public:
    void push(const T& data) {
        std::unique_lock<std::mutex> lock(_mtx);
        _data.push(data);
        _cv.notify_all();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(_mtx);
        while (_data.empty()) {
            _cv.wait(lock);
        }

        T data = _data.front();
        _data.pop();
        return data;
    }

private:
    std::queue<T> _data;
    std::mutex _mtx;
    std::condition_variable _cv;
