['Here is a high level code outline of how to implement this:

```cpp
#include <boost/beast/http.hpp>
#include <boost/asio/ssl.hpp>
#include <nlohmann/json.hpp>

class NetworkClient {
public:
    using SSLSocket = boost::asio::ssl::stream<boost::asio::ip::tcp::socket>;

    NetworkClient() : ssl_context_(boost::asio::ssl::context::tlsv12) {}
    ~NetworkClient();

    void Initialize(std::string server, std::string path);
    nlohmann::json SendRequest(nlohmann::json requestBody, const char* method = "POST");

private:
    boost::asio::ssl::context ssl_context_;
    SSLSocket socket_{ioc_, ssl_context_};
    std::string server_;
    std::string path_;

    void Connect();
    bool IsConnectionOpen() const;
    nlohmann::json ReceiveResponse(boost::beast::http::response<boost::beast::http::dynamic_body>& response);
};

void NetworkClient::Initialize(std::string server, std::string path) {
    server_ = server;
    path_ = path;
}

nlohmann::json NetworkClient::SendRequest(nlohmann::json requestBody, const char* method) {
    Connect();

    boost::beast::http::request<boost::beast::http::string_body> req{method, path_, 11};
    req.set(boost::beast::http::field::host, server_);
    req.set(boost::beast::http::field::user_agent, BOOST_BEAST_VERSION_STRING);
    req.set(boost::beast::http::field::content_type, "application/json");
    req.body() = requestBody.dump();

    boost::beast::http::write(socket_, req);

    boost::beast::flat_buffer buffer;
    boost::beast::http::response<boost::beast::http::dynamic_body> res;
    boost::beast::http::read(socket_, buffer, res);

    return ReceiveResponse(res);
}

void NetworkClient::Connect() {
    if (!IsConnectionOpen()) {
        // Fetch server and path from external config management system.
        boost::asio::ip::tcp::resolver resolver{ioc_};
        boost::beast::get_lowest_layer(socket_).connect(resolver.resolve(server_, "443"));

        socket_.handshake(boost::asio::ssl::stream_base::client);
    }
}
```
Please note that this is a high level overview and does not contain all of the implementation details such as error handling, connection pooling, rate limiting or retry logic which are very complex to implement. 

