['The implementation of such a service is complex and cannot be fully covered within this limited space. However, I can provide you with an outline of how to approach the problem using C#. Please note that this example uses the StackExchange.Redis library for Redis caching, Newtonsoft.Json for JSON deserialization, and System.Security.Cryptography namespace for AES encryption. Also, please note that error handling is kept at a minimum level.

```csharp
using StackExchange.Redis;
using System.Text;
using System.Security.Cryptography;
using Newtonsoft.Json;
using System;
using System.Threading.Tasks;

public class DataProcessingService<T> where T : new()
{
    private readonly byte[] key, iv;
    private readonly ConnectionMultiplexer redis;
    private static readonly SemaphoreSlim semaphore = new(1000);

    public DataProcessingService(string redisConnectionString, string key, string iv)
    {
        this.key = Encoding.UTF8.GetBytes(key);
        this.iv = Encoding.UTF8.GetBytes(iv);
        redis = ConnectionMultiplexer.Connect(redisConnectionString);
    }

    public async Task ProcessDataAsync(string data, Func<byte[], T> deserializer)
    {
        await semaphore.WaitAsync();

        try
        {
            var decryptedData = DecryptAesCbc(Convert.FromBase64String(data), this.key, this.iv);

            var obj = deserializer(decryptedData);

            // Store or process the object here...
            await StoreObjectInRedisAsync(obj);
        }
        finally
        {
            semaphore.Release();
        }
    }

    private static byte[] DecryptAesCbc(byte[] data, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Padding = PaddingMode.PKCS7;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        return PerformCryptography(data, decryptor);
    }

    private static byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using var memoryStream = new MemoryStream();
        using var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write);

        cryptoStream.Write(data, 0, data.Length);
        cryptoStream.FlushFinalBlock();

        return memoryStream.ToArray();
    }

    private async Task StoreObjectInRedisAsync(T obj)
    {
        var db = redis.GetDatabase();
        string serializedObj = JsonConvert.SerializeObject(obj);

        await db.StringSetAsync("Key", serializedObj, expiry: TimeSpan.FromMinutes(10)); // Example usage of Redis
    }
}
``` 
This is a basic example and does not cover all the required features such as versioning, configuration management, integration with external systems etc. For real-world use case, you would need to handle exceptions properly, add additional error handling, possibly introduce logging and metrics, design more scalable architecture, write tests etc. 

