['This is quite a complex task which involves designing the whole architecture of a distributed system in Go and writing C functions for memory management. Unfortunately, it's not possible to provide the entire code here due to the complexity and size of the project but I can give you some snippets that may help you get started:

1) A simple goroutine-based log processing system:
```go
package main

import (
	"fmt"
	"log"
	"math/rand"
	"time"
)

type LogData struct {
	Time  time.Time
	Level string
	Msg   string
}

func ProcessLog(dataCh chan LogData, done chan bool) {
	for data := range dataCh {
		// Here goes the logic to process the log
		fmt.Println("Processing: ", data)
	}
	done <- true
}

func main() {
	const (
		numWorkers = 4
		totalLogs  = 100
	)

	dataCh := make(chan LogData, numWorkers)
	done := make(chan bool)

	for i := 0; i < numWorkers; i++ {
		go ProcessLog(dataCh, done)
	}

	for i := 0; i < totalLogs; i++ {
		dataCh <- LogData{time.Now(), "info", fmt.Sprintf("log %d", rand.Intn(100))}
	}

	close(dataCh)

	for i := 0; i < numWorkers; i++ {
		<-done
	}

	fmt.Println("All log processing is done.")
}
```
2) A C function to manage memory for `offsets`, `keys` and `records`:
```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *offsets;
    int *keys;
    long *records;
} LogData;

void allocateMemory(LogData* log, size_t size) {
    log->offsets = malloc(sizeof(int) * size);
    if (!log->offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    log->keys = malloc(sizeof(int) * size);
    if (!log->keys) {
        perror("Failed to allocate memory for keys");
        free(log->offsets);
        exit(EXIT_FAILURE);
    }

    log->records = malloc(sizeof(long) * size);
    if (!log->records) {
        perror("Failed to allocate memory for records");
        free(log->offsets);
        free(log->keys);
        exit(EXIT_FAILURE);
    }
}

int main() {
    const int size = 10;

    LogData log;
    allocateMemory(&log, size);

    // Fill arrays with random values
    for (int i = 0; i < size; ++i) {
        log.offsets[i] = rand() % 100;
        log.keys[i] = rand() % 100;
        log.records[i] = rand() % 100;
    }

    // Free the memory when you're done
    free(log.offsets);
    free(log.keys);
    free(log.records);
}
```
Please note that this is a very high-level overview and doesn't cover all details, but it should give you an idea about the general direction to take. It's recommended to break down your design into smaller, manageable tasks and tackle each one step by step.
