['```c
#include <stdlib.h>
#include <string.h>
#include "external_db_library.h"

typedef struct {
    double timestamp;
    float metric;
    char* metadata;
} DataPoint;

DataPoint* newDataPoint(double timestamp, float metric, const char* metadata) {
    DataPoint *dp = (DataPoint*)malloc(sizeof(DataPoint));

    if (dp == NULL) {
        return NULL; // handle memory allocation failure here
    }

    dp->timestamp = timestamp;
    dp->metric = metric;
    dp->metadata = malloc(strlen(metadata) + 1);

    if (dp->metadata == NULL) {
        free(dp); // handle memory allocation failure here
        return NULL;
    }

    strcpy(dp->metadata, metadata);
    return dp;
}

void deleteDataPoint(DataPoint* dp) {
    if (dp != NULL) {
        free(dp->metadata);
        free(dp);
    }
}

int storeDataPointToDB(DataPoint* dp, DBHandle* db, int retryCount) {
    int status = external_db_library_write(db, dp->timestamp, dp->metric, dp->metadata);

    if (status == EXTERNAL_LIBRARY_FAILURE && retryCount > 0) {
        sleep((1 << retryCount) * 1000); // exponential backoff
        return storeDataPointToDB(dp, db, retryCount - 1);
    } else if (status == EXTERNAL_LIBRARY_FAILURE) {
        return status;
    } else {
        return SUCCESS;
    }
}
```
