```java
import java.util.*;

// Simplified version of a distributed Job Management System 
public class DistributedJobManagementSystem {

    // Structure for offsets, keys and records
    private Map<Integer, Long> offsetMap;
    private List<Record> recordList;
    private Queue<Request> requestQueue;

    public DistributedJobManagementSystem() {
        this.offsetMap = new HashMap<>();
        this.recordList = new ArrayList<>();
        this.requestQueue = new LinkedList<>();
    }

    // Simplified version of a record
    private class Record {
        Integer key;
        Long offset;

        public Record(Integer key, Long offset) {
            this.key = key;
            this.offset = offset;
        }
    }

    // Simplified version of a request
    private interface Request {}

    // Implementation of adding a record
    public synchronized void addRecord(Integer key, Long offset) {
        Record newRecord = new Record(key, offset);
        this.offsetMap.put(newRecord.key, newRecord.offset);
        this.recordList.add(newRecord);
    }

    // Implementation of removing a record
    public synchronized void removeRecord(Integer key) {
        Long removedOffset = this.offsetMap.remove(key);
        for (Iterator<Record> iterator = recordList.iterator(); iterator.hasNext(); ) {
            Record record = iterator.next();
            if (record.key == key && record.offset == removedOffset) {
                iterator.remove();
            }
        }
    }

    // Implementation of adding a request to the queue
    public synchronized void addRequest(Request request) {
        this.requestQueue.add(request);
    }

    // Simplified version of processing requests from the queue
    public void processRequests() {
        while(!this.requestQueue.isEmpty()) {
            Request request = this.requestQueue.poll();
            if (request instanceof AddRecordRequest) {
                addRecord(((AddRecordRequest) request).key, ((AddRecordRequest) request).offset);
            } else if (request instanceof RemoveRecordRequest) {
                removeRecord(((RemoveRecordRequest) request).key);
            }
        }
    }

