public class DataLoader : IDataLoader
{
    private readonly string _filePath;
    private readonly ILogger _logger;

    public DataLoader(string filePath, ILogger logger)
    {
        if (string.IsNullOrEmpty(filePath)) throw new ArgumentException("Invalid file path");

        _filePath = filePath;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<byte[]> LoadFileAsync()
    {
        try
        {
            using (var sourceStream = new FileStream(_filePath, FileMode.Open))
            {
                var result = new byte[sourceStream.Length];
                await sourceStream.ReadAsync(result, 0, (int)sourceStream.Length);

                _logger.Information("File loaded successfully");

                return result;
            }
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Failed to load file");

            throw;
        }
    }
}
