#include <openssl/aes.h>
#include <openssl/sha.h>
#include <string.h>

typedef struct {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} AES256CBCContext;

AES256CBCContext* initializeAES256CBC(const char* password) {
    AES256CBCContext* ctx = malloc(sizeof(AES256CBCContext));

    // Generate a 32 byte key using SHA-256 hash of the password
    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);

    // Set IV to all zeros for this example
    memset(ctx->iv, 0, AES_BLOCK_SIZE);

    // Initialize the cipher context with the key and iv
    if (AES_set_encrypt_key(key, 256, &ctx->key) < 0) {
        free(ctx);
        return NULL;
    }

    return ctx;
}
```
