// Define the trait for logging processors
pub trait LogProcessor {
    fn process(&self, log: &str);
}

// Simple implementation of a log processor
struct ConsoleLogProcessor;
impl LogProcessor for ConsoleLogProcessor {
    fn process(&self, log: &str) {
        printlnLoggerust::log(rust::logLevel::Debug, log);
    }
}

pub struct Logger {
    pub processors: Vec<Box<dyn LogProcessor>>,
}

impl Logger {
    pub fn new() -> Self {
        Logger { processors: vec![Box::new(ConsoleLogProcessor)] }
    }

    pub fn log(&self, msg: &str) {
        for processor in self.processors.iter() {
            processor.process(msg);
        }
    }
}
