std::string hash_file(const std::string& path) {
    using namespace DynamicDataPipeline;

    constexpr auto BUFSIZE = 4096;  // chunk size to read file in
    char buf[BUFSIZE];

    MD5 md5;

    ifstream infile(path, ifstream::binary);
    while (infile.good()) {
        infile.read(buf, BUFSIZE);
        auto bytes_read = infile.gcount();

        md5.update(reinterpret_cast<uint8_t*>(buf), bytes_read);  // update MD5 with new chunk
