6. The function to copy bytes from list of buffered data chunks into a new buffer using `std::vector<std::byte>` could be implemented as follows:
```cpp
void CopyBytes(const std::list<std::vector<std::byte>>& source, size_t numOfBytes, std::byte* destination) {
    size_t bytesCopied = 0;
    for (auto const& buffer : source) {
        if ((buffer.size() - bytesCopied) >= numOfBytes) {
            std::memcpy(destination, &buffer[bytesCopied], numOfBytes);
            return;
        } else {
            std::memcpy(destination, &buffer[0] + bytesCopied, buffer.size() - bytesCopied);
            destination += (buffer.size() - bytesCopied);
            numOfBytes -= (buffer.size() - bytesCopied);
        }
    }
}
```
